(window.STORIES=window.STORIES||[]).push(...[{"n": 258, "l": "الجزء 232 | الاحداث الاخيره في حيات رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_واثنين_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#الأحداث_الأخيرة_في_حياة_رسول_الله\nاتكلمنا المرة إللي فاتت عن بداية مرض رسول الله ﷺ وقلنا مرضه كان عبارة عن صداع وحُمّى شديدة، والمرض كان كل شوية بيشتد على رسول الله ﷺ،\nفي يوم الأربعاء السابع من شهر ربيع الأول رسول الله ﷺ ارتفعت حرارة رسول الله ﷺ جدا لدرجة إنه بقى يفقد الوعي من شدة الحرارة،\nفلما أفاق في مرة من المرات قال:\n\"هَرِيقُوا عَلَيَّ مِن سَبْعِ قِرَبٍ، لَمْ تُحْلَلْ، أوْكِيَتُهُنَّ لَعَلِّي أعْهَدُ إلى النَّاسِ\"\nالقِرْبة حاجة كده زي زجاجة الماء، وبتبقى من الجلد ولها رباط يقفلها،\nفرسول الله ﷺ بيقولهم هاتوا سبع قِرب من الماء مقفولين محدش لسه فتحهم ولا استعمل المية إللي فيهم،\nوفي رواية تانية بتقول إنه طلب منهم إن قِرَب الماء دي تكون من آبار مختلفة،\nوقالهم لما يجيبوها يصبوا عليه المية إللي في القِرب دي،\nوكان طلب رسول الله ﷺ صب الماء ده من باب التداوي عشان يخفض الحرارة،\nفجاءوا بقرب الماء وزوجات رسول الله ﷺ أجلسوه في  مِخْضَبٍ لِحَفْصَةَ زوجة رسول الله ﷺ،\nوالمِخْضَبٍ عبارة عن وعاء من نحاس،\nحاجة زي الطشت كده لو تعرفوه، أو مجازا يعني نقدر نقول بانيو،\nالمهم، أجلسوه فيه وقعدوا يصبوا عليه الماء من القِرَب السبعة،\nوبعدين أشار رسول الله ﷺ لزوجاته وقال حَسْبُكم حَسْبُكم،\n يعني خلاص كفاية كده انتم صبيتم عليّ من السبع قِرَب،\nبعدها حس رسول الله ﷺ بنشاط فربط رأسه وخرج وصلى بالناس،\nوخلال الأيام إللي فاتت دي كان رسول الله ﷺ مع شدة مرضه كان بيتحامل على نفسه وبيصلي بالناس جماعة وهو جالس،\nبعد الصلاة قعد رسول الله ﷺ على المنبر وخطب في الصحابة آخر خطبة قبل موته، \nوالخطبة دي اسمها 《خطبة مرض الموت》،\nقال رسول الله ﷺ بعد ما حمد الله وأثنى عليه:\n\"إنه ليس من الناسِ أحدٌ أمَنَّ عليَّ في نفسِه ومالِه من أبي بكرِ ابنِ أبي قحافةَ، \nولو كنتُ مُتخذًا من الناسِ خليلًا لاتخذتُ أبا بكرٍ خليلًا ، ولكن خُلَّةُ الإسلامِ أفضلُ، سُدُّوا عني كلَّ خَوخَةٍ في هذا المسجدِ ، غيرَ خَوخَةِ أبي بكرٍ...\"\nيعني إن أكثر الناس جُودًا وسَمَاحةً لنا بنفسِه ومالِه هو أبو بكر الصديق رضي الله عنه، \nولو كان رسول الله ﷺ مُتخذ خليل من أصحابه لاتخذ أبا بكر خليلا، ولكن رسول الله ﷺ خليل الله،\nومعنى خليل الله: المُنقطِع إليه، \nيعني درجة شديدة جدا من القرب والحب، ولكن علاقة رسول الله ﷺ بأبي بكر هي أخوة الإسلام واختصاصه بمحبة زيادة عن غيره،\nوكان بعض الصحابة فتحوا أبواب من بيوتهم يخرجوا  منها على المسجد مباشرة ومنهم أبو بكر،\nفإكراما لأبي أبكر، أمر رسول الله ﷺ إن كل خَوخَةِ يعني الباب الصغير إللي بيطل على المسجد ده وبيخرج منه الناس للمسجد يتسد ما عدا باب أبي بكر.\nأكمل رسول الله ﷺ كلامه وقال:\n\"إنَّ عَبْدًا خَيَّرَهُ اللَّهُ بيْنَ أنْ يُؤْتِيَهُ مِن زَهْرَةِ الدُّنْيا ما شاء وبيْنَ ما عِنْدَهُ، فاخْتارَ ما عِنْدَهُ...\"\nهنا رسول الله ﷺ بيحكي عن عبد ربنا أعطى له اختيارين:\nإنه يقعد في الدنيا ويعيش فيها زي ما هو عايز أو إنه يموت ويدخل الجنة،\nفالصحابة فكروا إن دي من ضمن القصص إللي رسول الله ﷺ كان بيحكيها لهم قبل كده فاستقبلوا الكلام عادي،\nوفجأة لقوا أبا بكر بيبكي بشدة وبيقول:\n\"فَدَيْناكَ بآبائِنا وأُمَّهاتِنا\"\nفالصحابة استغربوا منه، إيه في إيه، رسول الله ﷺ بيحكي عن عبد ربنا بيخيره، تقوم انت تقول لرسول الله ﷺ فديناك بآبائنا وأمهاتنا!\n الكلام مش راكب وملوش دعوة ببعضه خالص!\nلكن أبو بكر رضي الله عنه كان هو أعلم الناس برسول الله ﷺ فعرف إنه هو العبد المُخيّر، وإن خلاص كده الرحلة انتهت وإن صاحبه رسول الله ﷺ هيموت.\n☆رسول الله ﷺ لحد آخر أيامه في الدنيا بيفكرنا إن الدنيا مهما كانت شكلها جميل ومُغرية وفيها من المُتع الكتيرة فهي زي الزهرة عمرها قليل،\nالزهرة ممكن نستمتع بيها يوم أو اثنين وبعدها هتموت ومش هيكون لها قيمة، فكذلك الدنيا، مهما عاش الإنسان فيها مُنعّم فالنعيم ده هينتهي لا محالة\n◇ممكن حد كان يتمنى ولو كفكرة بس، إن رسول الله ﷺ يفضل عايش ويختار الدنيا وأهه نشوفه وكمان طول ما هو موجود هيقيم شرع ربنا،\nلكن يا جماعة لو فكرنا كده بعقلنا هنلاقي الأمنية دي فيها أنانية شوية، \nتخيلوا كده إن واحد يعيش يتعرف على ناس ويشيل همهم وهم تعليمهم وهدايتهم ويحبهم ويحبوه وحياتهم ترتبط ببعض،\nوبعد كده يشوفهم بيموتوا واحد ورا التاني، وده مش هيتكرر مرة أو اتنين ده هيفضل كده آلاف السنين، \nرسول الله ﷺ مات من ألف وأربعمائة سنة، والله أعلم باقي كم سنة لحد نهاية الدنيا،\nمتخيلين كمية الألم والحزن إللي كان هيعيشها بسبب فقده لأصحابه وأحبابه على مدار السنين دي كلها،\nومتنسوش إنه في الأول وفي الآخر بشر، يعني بيشعر بالحزن والألم، فمين يستحمل كل ده\nوطبعا لأن رسول الله ﷺ أحب إلينا حتى من نفسنا، فاحنا منتمناش لرسول الله ﷺ إنه يتعرض لألم زي ده،\nفالحمد لله إن رسول الله ﷺ مخترش الخلود في الدنيا، تكفيه الآلام إللي مرت بيه ﷺ،\nبس مش معنى كلامي ياجماعة إننا منتمناش رؤية رسول الله ﷺ، دي حاجة ودي حاجة،\nحتى رسول الله ﷺ كان يقول:\n\"مِنْ أشَدِّ أُمَّتي لي حُبًّا، ناسٌ يَكونُونَ بَعْدِي، يَوَدُّ أحَدُهُمْ لو رَآنِي بأَهْلِهِ ومالِهِ\"\nيعني رسول الله ﷺ بيقول إن في ناس من شدة حبهم له  يتمنوا لو إنهم شافوا رسول الله ﷺ ولو كان في مقابل ده إنهم هيفقدوا أهلهم وأموالهم،\nمش ساعات بتسمعوا واحد يقول أنا أدفع عمري وأعمل كذا أو أعرف كذا،\nأهه برده الناس دي عندها استعداد إنها تفقد أهلها وأموالها في مقابل إنها تشوف رسول الله ﷺ من شدة حبها له،\nوده علامة على قوة الإيمان\nيعني الواحد فينا لما يقرأ سيرة رسول الله ﷺ ويشوف حياته كانت عاملة إزاي؛ يتمنى إنه كان يبقى معاه عشان ينصره في الحرب ويواسيه في الشدة وهكذا زي ما الصحابة عملوا كده مع رسول الله ﷺ.\n☆ملحوظة:\nتخيير الأنبياء بين الموت والخلود في الدنيا دي حاجة خاصة بيهم هم، ومفيش تعارض بين التخيير ده وبين قول ربنا:\n\"وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الخُلْدَ أَفَإِنْ مِتَّ فَهُمُ الخَالِدُونَ\"\nلأن ربنا عالم من البداية أصلا إن الأنبياء لما يُخيّروا هيختاروا الموت وما عند الله،\nوبالتالي ربنا حدد الآجال والأعمار، بدون زيادة فيها ولا نُقصان\nأكمل رسول الله ﷺ خطبته وقال:\n\"إنَّ النَّاسَ يَكْثُرُونَ ويَقِلُّ الأنْصَارُ، حتَّى يَكونُوا في النَّاسِ بمَنْزِلَةِ المِلْحِ في الطَّعَامِ، \nفمَن ولِيَ مِنكُم شيئًا يَضُرُّ فيه قَوْمًا ويَنْفَعُ فيه آخَرِينَ، فَلْيَقْبَلْ مِن مُحْسِنِهِمْ ويَتَجَاوَزْ عن مُسِيئِهِمْ...\"\nيعني الناس إللي بيدخلوا الإسلام بصفة عامة بيكثروا،\nأما الأنصار فعددهم بيقل، وهيفضل عددهم يقل لحد ما يكونوا عددهم زي كمية الملح إللي بتتحط في الطعام، \nيعني شوفوا حلة الأكل الكبيرة بنحط عليها كمية ملح صغيرة أد إيه،\nفرسول الله ﷺ بيشبه حجم عدد الأنصار بالنسبة لباقي الناس إللي هيدخلوا في الإسلام،\nورسول الله ﷺ بينبه أي واحد هيكون في موضع حكم وله سلطة على الناس وإنه يقدر بسبب سلطانه ده يضر وينفع الناس؛\nإنه يقبل من المُحسن من الأنصار ويتجاوز عن المسيء منهم،\nطبعا ده في غير الحدود،\nفالشاهد من الكلام إن رسول الله ﷺ وصّى الناس بالأنصار،\nواحنا شوفنا قبل كده مكانة الأنصار عند رسول الله ﷺ ودعوته لهم ولأبنائهم ولأبناء أبنائهم.\nأكمل رسول الله ﷺ وصاياه الأخيرة وقال:\n\" أَلَا وَإِنَّ مَنْ كَانَ قَبْلَكُمْ كَانُوا يَتَّخِذُونَ قُبُورَ أَنْبِيَائِهِمْ وَصَالِحِيهِمْ مَسَاجِدَ، أَلَا فَلَا تَتَّخِذُوا الْقُبُورَ مَسَاجِدَ، إِنِّي أَنْهَاكُمْ عَنْ ذَلِكَ\"\nيعني رسول الله ﷺ بيذم اليهود والنصارى إللي كانوا بيصلوا عند قبور أنبيائهم وكبار الصالحين أو حول قبورهم،\nوبيأمر المسلمين إنهم ميعملوش زيهم، فلا يجوز للمسلمين أن يبنوا على القبور قبة ولا مسجد، \nولا يصلوا عند القبر، لا فرض ولا نفل إلا صلاة الجنازة،\nيعني إذا مات وحضروا في القبر وصلى عليه بعض الناس فمفيش مشكلة، أو صلوا عليه عند القبر فده جائز\nوطبعا كلام رسول الله ﷺ هنا فيه إشارة إنه هيموت قريب.\nبعد ما انتهى رسول الله ﷺ من الخطبة نزل من على المنبر ودخل بيت عائشة رضي الله عنها،\nفي اليوم التالي، يوم الخميس الثامن من ربيع الأول حصل حدث مهم،\nاشتد الوجع على رسول الله ﷺ وكان في مجموعة من الصحابة موجودين معاه وكانوا جايين يزوروه وكان من الموجودين عمر بن الخطاب رضي الله عنه، فقال لهم رسول الله ﷺ:\n\"ائْتُونِي اَكْتُبْ لَكُمْ كِتَابًا لاَ تَضِلُّوا بَعْدِي\"\nيعني بيأمرهم إنه يأتوه بورقة وقلم عشان يخلي حد يكتب إللي هيقول له عليه وفيه هداية للأمة من بعده،\nفبعض الموجودين ومنهم عمر رضي الله عنه شافوا إنه في تعب وإعياء شديد، فتأخروا في في إحضار الكتاب،\nوشافوا إن إللي في القرآن العظيم من الهداية يكفيهم عن إجهاد رسول الله ﷺ بالكتابة،\nفقال عمر:\n\" إِنَّ النَّبِيَّ ﷺ غَلَبَهُ الْوَجَعُ وَعِنْدَنَا كِتَابُ اللَّهِ حَسْبُنَا\"\nوده كان من فقه عمر رضي الله عنه؛ لأنه خاف إن رسول الله ﷺ يكتب أمور ممكن يعجزوا إنهم يعملوها وبكده يستحقوا العقوبة؛\nلأن كلام رسول الله ﷺ منصوص فمفيش فيه مجال للاجتهاد، فقال عمر حَسْبنَا كِتَاب اللَّه؛ لأن ربنا قال: \n\"مَا فَرَّطْنَا فِي الْكِتَاب مِنْ شَيْء \"\nوقَال: \n\"الْيَوْم أَكْمَلْت لَكُمْ دِينكُمْ \"\nفكان معروف إن ربنا أكمل دينه والأمة لن تضل مادامت متبعة لكتاب الله،\nوزي ما قلنا هو كان عايز يخفف عن رسول الله ﷺ ومش عايز يجهده،\nلكن مجموعة تانية كانوا عايزين ينفذوا أمر رسول الله ﷺ بإنهم يأتوه بكتاب عشان يكتبوا إللي هو عايزه،\nفحصل خلاف بين الصحابة عند رسول الله ﷺ وهو مريض على فراشه،\nفريق عايز يجيب الكتاب لرسول الله ﷺ وفريق بيقول لأ مش لازم،\nفلما حصل الخلاف منهم رجع رسول الله ﷺ في كلامه وقال خلاص إنه مش عايز حاجة ووصاهم بلسانه وقال:\n\"أَخْرِجُوا الْمُشْرِكِينَ مِنْ جَزِيرَةِ الْعَرَبِ،  وأَجِيزُوا الْوَفْدَ بِنَحْوِ مَا كُنْتُ أُجِيزُهُمْ\"\nيعني أكرموا الوفود زي ما أنا كنت بكرمهم، وأخرجوا المشركين من جزيرة العرب واحنا اتكلمنا عن النقطة دي بالتفصيل واحنا بنتكلم عن آية القتال فمش هنعيد الكلام.\n☆ملحوظة:\n أَمْر رسول الله ﷺ للصحابة إنهم يأتوه بكتاب مكنش أمر إلزامي واجب التنفيذ، \nوالدليل على كده إنه لم يغضب منهم ﷺ بسبب إللي حصل، \nولم يُنكر على المجموعة إللي تباطأت عن إحضار الكتاب،\nولم يُنزّل الله تعالى فيهم آيات تُتلى كما هي عادة القرآن \n بل سكت وأقرّهم، \nولم يُكرر رسول الله ﷺ طلبه بإحضار الكتاب، سواء في اللحظة دي أو خلال الأيام إللي عاشها بعد كده،\nومفيش حد يقدر يمنع رسول الله ﷺ يعمل أي حاجة هو عايزها أصلا، \nفموضوع كتابة الكتاب ده كان حاجة اختيارية رسول الله ﷺ عايز يعملها ورجع فيها بسبب الخلاف إللي حصل بينهم،\nفالخلاف إللي حصل بينهم ده كان زي الخلاف إللي حصل يوم الحديبية لما أمرهم رسول الله ﷺ بالتحلل فتأخروا رجاء نزول الوحي بإنهم يكملوا في العمرة لو تفتكروا،\nوزي الخلاف إللي حصل في أسرى بدر يعملوا فيهم إيه وغيرها من الأمور إللي رسول الله ﷺ كان حاضرها وسكت عنها،\nفالشاهد من الكلام إن الصحابة لم يعصوا أمر رسول الله ﷺ ولكن اجتهدوا في مسألة الأمر فيها اختياري\nاستمر وجع رسول الله ﷺ الشديد، فزوجات رسول الله ﷺ وبعض الصحابة ظنوا إن رسول الله ﷺ عنده مرض ذات الجَنَب،\nوهو مرض يصيب الرئة، ومن أعراضه الحمى وضيق في التنفس، \nفقرروا إنه يَلُدُّوه، و اللَّدود هو الدواء الذي يُصَب في أحد جانبي فم المريض ويُسْقاه،\nشوفوا كده لما نكون عايزين نسقى طفل صغير دواء وهو تعبان وهمدان مش بنسقيه الدواء في جانب الفم عشان يعرف يبلعه من غير ما يشرق،\nأهه زوجات رسول الله ﷺ كان عايزين يعملوا كده، والدواء إللي كانوا هيسقوه لرسول الله ﷺ كان مُر،\nفلما رسول الله ﷺ عرف إنهم عايزين يسقوه الدواء بالطريقة دي وهو كان تعبان ومش قادر يتكلم أشار إليهم بإيده:\nأن لا تَلُدُّوني.\nففكروا إن رسول الله ﷺ مش عايز ياخد الدواء زي المريض كده إللي بيرفض الدواء المر،\nوكان رسول الله ﷺ بيغمى عليه كل شوية، فلما أفاق من الإغماء عرف إنهم سقوه الدواء بالطريقة دي،\nفقال لهم رسول الله ﷺ:\n\"لا يبقى أحدٌّ إلا لُدَّ غيرُ العباس؛ فإنه لم يَشهَدكم\"\n《الحديث موجود في البخاري ومسلم》\nيعني رسول الله ﷺ  أمر كل الموجودين في الغرفة إنهم يشربوا من نفس الدواء إللي شرّبوه لرسول الله ﷺ بدون إذنه ما عدا العباس لأن العباس مكنش معاهم في الموضوع من البداية ولكنه موجود دلوقتي في الغرفة،\nففعلا كل إللي كان في الغرفة شربوا الدواء، رجال ونساء، حتى ميمونة زوجة رسول الله ﷺ، مع إنها كانت صائمة اليوم ده، لكنها شربته امتثال لأمر رسول الله ﷺ\nورسول الله ﷺ عمل كده عشان كل واحد منهم يذوق عاقبةَ تسرُّعه في شيء يؤذي المريض الذي لا يستطيع دفاعًا ولا منعًا،\nفكان الهدف من فعل رسول الله ﷺ هو عقوبة لهم بغرض التأديب عشان ميعملوش كده تاني وخصوصا إنهم مسمعوش كلامهم وهو أمرهم إنهم ميعملوش كده،\nوالعقوبة كانت على إللي سقى رسول الله ﷺ الدواء وكمان إللي مسقاهوش ولكنه كان موافق على إللي بيحصل،\nوده بيؤكد على شيء مهم،\nوهي إن إللي بيشوف خطأ ولم ينكره فهو شريك في الإثم وبالتالي هو شريك في العقوبة،\nفالموافق على الجِناية وإن لم يُباشِرها هو شريك الجاني، زي ما المُستمع للغِيبة شريك المُغتاب في الإثم،\nواحنا اتكلمنا كتير عن النقطة دي في قصص الأنبياء وفي السيرة فمش هعيد عشان مطولش عليكم.\nهنكمل إن شاء الله المرة الجاية الأحداث الأخيرة في حياة رسول الله ﷺ.\nمصادر جزء النهاردة في التعليقات"}, {"n": 259, "l": "الجزء 233 | وفاة رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثلاثة_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#وفاة_رسول_الله_ﷺ \nقبل القراءة:\nحلقة النهاردة والحلقة الجاية أصعب حلقات السيرة، فاللي مش مستعد نفسيا ميقرأش، أنا شخصيا لولا إني مضطر أكتب الجزء ده والله ولا كنت اتكلمت فيه أصلا من صعوبته وألمه على النفس.\nاتكلمنا المرة إللي فاتت عن الكتاب إللي رسول الله ﷺ كان عايز يكتبه وبعدين رجع في كلامه بعد ما حصل الحوار إللي حكينا عنه،\nوقلنا إن الكلام ده كان يوم الخميس الثامن من ربيع الأول من السنة الحادية عشرة من الهجرة،\nوكان رسول الله ﷺ بيصلي بالناس خلال الفترة دي كلها لحد صلاة مغرب يوم الخميس ده،\nصلى رسول الله ﷺ بالناس المغرب وقرأ سورة المرسلات في الصلاة،\nودي كانت آخر صلاة صلاها رسول الله ﷺ بالناس وآخر آيات سمعوها منه ﷺ؛ لأن الوجع اشتد عليه بعدها ومبقاش يعرف يخرج للصلاة، ولما جاءت صلاة عشاء يوم الخميس كان أغمي عليه، فلما أفاق سأل:\n\"أصَلَّى النَّاسُ؟\"\nفقالوا:\n\"لَا، هُمْ يَنْتَظِرُونَكَ\"\nيعني الناس مستنيينك تصلي بيهم، فقال:\n\"ضَعُوا لي مَاءً في المِخْضَبِ\"\nيعني طلب منهم إنهم يضعوا له ماء في طبق كده كبير كانوا بيستعملوه في غسل الملابس،\nفبعد ما وضعوا الماء قام رسول الله ﷺ واغتسل عشان يخفف شوية من الحرارة عشان يعرف يصلي،\nفلما أراد إنه يقوم أغمي عليه مرة تانية، فلما أفاق سأل:\nأصَلَّى النَّاسُ؟\nقالوا له:\n\"لَا، هُمْ يَنْتَظِرُونَكَ\"\nفطلب منهم تاني إنهم يضعوا الماء في المِخْضَبِ، فاغتسل رسول الله ﷺ ولما جه يقوم أغمي عليه مرة تانية، واتكرر الموضوع تلات مرات، والناس قاعدين مجتمعين في المسجد مستنيين رسول الله ﷺ،\nبعد كل المحاولات دي من رسول الله ﷺ إنه يصلي صلاة الجماعة ومش عارف، عرف إنه مش هيقدر يخرج لصلاة الجماعة لأول مرة في حياته ﷺ،\nولكنه في نفس الوقت كان حريص على صلاة أصحابه وإنهم ميضيعوش الصلاة فكان كل شوية يسأل إذا كانوا صلوا أو لأ،\nفي الوقت ده قرر رسول الله ﷺ إنه يخلي واحد من الصحابة ينوب عنه لإمامة المسلمين في الصلاة، فقال لهم:\n\"مُرُوا أبَا بَكْرٍ فَلْيُصَلِّ بالنَّاسِ\"\nيعني قولوا لأبي بكر يصلي بالناس، فالسيدة عائشة خافت إن المسلمين يتشاءموا بأبي بكر لو وقف مكان رسول الله ﷺ،\nفقالت السيدة عائشة:\n\"إنَّ أبَا بَكْرٍ رَجُلٌ رَقِيقٌ، إذَا قَرَأَ غَلَبَهُ البُكَاءُ\"\nيعني أبو بكر رضي الله عنه بيتأثر بالقرآن لدرجة إنه أول ما بيقرأ بيبكي، فالناس كده مش هتسمع هو بيقول إيه أصلا،\nفقالت لرسول الله ﷺ:\n\"فلوْ أمَرْتَ عُمَرَ\"\nيعني خلي عمر هو إللي يصلي بيهم أحسن، فقال رسول الله ﷺ: \" قَالَ: مُرُوهُ فليُصَلِّي\"\nفقالت السيدة عائشة للسيدة حفصة إنها تقول لرسول الله ﷺ إن أبا رجل رقيق وإنه يخلي عمر هو إللي يصلي بيهم،\nفلما قالت حفصة لرسول الله ﷺ نفس كلام عائشة، فقال رسول الله ﷺ:\n\"مُرُوا أبَا بَكْرٍ أنْ يُصَلِّيَ بالنَّاسِ\"\nفأعادت عليه السيدة عائشة نفس كلامها، فغضب رسول الله ﷺ وقال:\n\"مُرُوهُ فليُصَلِّي، إنَّكُنَّ صَوَاحِبُ يُوسُفَ\"\nالمقصود بصواحب يوسف إنهن بيظهرن خلاف ما يبطن، يعني بيقولوا كلام ظاهره صحيح لكن مش هو ده إللي المقصود من كلامهم وإللي عايزينه فعلا،\nيعني أيوة فعلا أبو بكر رجل رقيق والناس ممكن متسمعش منه لكن مش هو ده السبب الحقيقي إللي خلاهم يعترضوا، في سبب تاني انتم مخبيينه وهو انكم مش عايزين الناس تتشائم من أبي بكر،\nوانتم عمالين تلحوا وأنا أعرضت عن الكلام أكثر من مرة فخلاص بقى نفذوا كلامي من غير ما نعيد ونزيد،\nوطبعا هنا في إشارة إن أبا بكر هو أفضل الناس عشان كده رسول الله ﷺ اختاره، وفيه إشارة كمان إنه أوْلَى الناس بالخلافة بعد رسول الله ﷺ،\nفلما وصل الموضوع لأبي بكر إن رسول الله ﷺ طلب إنه يصلي بالناس قال لعمر:\n\"يا عُمَرُ صَلِّ بالنَّاسِ\"\nفَقَالَ له عُمَرُ: \"أنْتَ أحَقُّ بذلكَ\"\nفصلى أبو بكر بالناس العشاء، فلما كان في الصلاة رسول الله ﷺ حس بخِفة فخرج للمسجد وهو مستند على العباس وعلي بن أبي طالب وكانت ورجله بتخط في الأرض،\nفلما رآه أبو بكر أراد أن يتأخَّرَ، \nيعني يرجع للوراء عشان رسول الله ﷺ يتقدم ويصلي هو بالناس، \nفأشار له النَّبيُّ ﷺ ألَّا يتأخَّرَ، وجلَس رسول الله ﷺ بجانبِه، فاقتدى أبو بكرٍ رضي الله عنه بصلاةِ النَّبيِّ ﷺ، واقتدَى النَّاسُ بصلاة أبي بكرٍ رضي الله عنه؛ \nيعني رسول الله ﷺ كان إمام لأبي بكر، وأبو بكر كان إمام للناس، لأنهم مكنوش شايفين رسول الله ﷺ ولا سامعين صوته،\nجاء يوم الجمعة وصلى أبو بكر بالناس كل الصلوات وخطب فيهم خطبة الجمعة، وكل ده ورسول الله ﷺ مريض،\n واستمر أبو بكر يصلي بالناس طول فترة مرض رسول الله ﷺ في آخر أيامه لحد ما مات،\nفي يوم الجمعة ده قال رسول الله ﷺ:\n\"لا يَمُوتَنَّ أَحَدُكُمْ إلَّا وَهو يُحْسِنُ باللَّهِ الظَّنَّ\"\n☆شوفوا يا جماعة،\nالإنسان لما بيتعرض لابتلاء شديد أو مرض شديد وكل شوية يشتد عليه المرض مع إن هو كويس وعلى طاعة، ساعات يصيبه الشك ويبدأ يتساءل هل ربنا مش راضي عني، طيب فين الغلط طيب فين المشكلة، وممكن يوصل معاه الموضوع إنه يُسيء الظن بالله،\nوأخطر وقت ممكن الإنسان يتعرض فيه لحاجة زي كده هو قبل ما يموت، \nفرسول الله ﷺ قبل ما يموت بثلاثة أيام وفي شدة مرضه\nبيقولنا مش معنى إن الواحد بيتعرض لبلاء شديد إنه يسيء الظن بالله، \nلأ، أحسنوا الظن بالله إن ربنا هيرحم عبده، ولازم العبد يتذكر  في اللحظة دي الآيات والأحاديث إللي جاءت عن كَرمِ اللهِ تَعالى وعَفوِه وما وَعَدَ به أَهلَ التَّوحيدِ،\nوإن مش معنى شدة المرض قبل موت العبد المؤمن إن ربنا غضبان عليه، بالعكس بقى، والدليل على كده شدة مرض رسول الله ﷺ قبل موته،\nفإذا كان رسول الله ﷺ وهو رسول الله تعرض للمرض الشديد ده، فمفيش مشكلة خالص لو تعرّض غيره للمرض والابتلاء الشديد\nفرسول الله ﷺ بيحذرنا من القنوط من رحمة الله عند اقتراب الموت وبيشجعنا على الرجاء في رحمة الله.\nجاء أسامة بن زيد بن حارثة رضي الله عنه عشان يطمئِن على رسول الله ﷺ، واحنا قلنا قبل كده إنه كان برة المدينة مخيم مع الجيش إللي هيخرج لقتال الروم في الشام،\nولكنه توقف لما عرف بمرض رسول الله ﷺ،\nفجاء ودخل على رسول الله ﷺ يزوره، فكان رسول الله ﷺ ينظر إلى أسامة ويشير إليه بإصبعه ويرفعها للسماء،\nفعرف أسامة إن رسول الله ﷺ بيدعي له، وكان عند رسول الله ﷺ العباس وعلي،\nطبعا مشاعر الصحابة لا تُوصف في الأيام دي، ناس مكنوش يطيقوا إن رسول الله ﷺ تصيبه شوكة بس، ومستعدين يفدوه بأرواحهم، وكان بيغتموا لحزنه،\nفجأة كده شايفين رسول الله ﷺ مريض مش قادر يتحرك وهم مش قادرين يعملوا له أي حاجة،\nمبقاش يصلي بيهم، ولا يخطب فيهم كالعادة، شايفين حد تاني هو إللي بيصلي وبيخطب،\nالمدينة كلها في قلق وحزن على رسول الله ﷺ،\nبعد ما خرج أسامة والعباس وعلي من عند رسول الله ﷺ الناس سألوا علي رضي الله عنه:\nيا أبَا حَسَنٍ، كيفَ أصْبَحَ رَسولُ اللَّهِ ﷺ؟\nيعني رسول الله ﷺ عامل إيه دلوقتي، فقال لهم:\n\" أصْبَحَ بحَمْدِ اللَّهِ بَارِئًا\"\nيعني هو أفاق من الإغماء إللي كان فيه، وبعدها العباس أخذ علي رضي الله عنه على جنب عشان يكلمه،\nقال العباس لعلي:\n\"وإنِّي واللَّهِ لَأَرَى رَسولَ اللَّهِ ﷺ سَوْفَ يُتَوَفَّى مِن وجَعِهِ هذا، إنِّي لَأَعْرِفُ وُجُوهَ بَنِي عبدِ المُطَّلِبِ عِنْدَ المَوْتِ، اذْهَبْ بنَا إلى رَسولِ اللَّهِ ﷺ فَلْنَسْأَلْهُ فِيمَن هذا الأمْرُ،\n إنْ كانَ فِينَا عَلِمْنَا ذلكَ، وإنْ كانَ في غيرِنَا عَلِمْنَاهُ، فأوْصَى بنَا\"\nيعني العباس بيقول لعلي إنه بيعرف علامات الموت في وجوه بني عبد المطلب، وهو شاف العلامات دي في وجه رسول الله ﷺ وهو خلاص هيموت،\nومفيش خليفة للمسلمين، فكان عايز يروح لرسول الله ﷺ ويسأله مين هو الخليفة بعده، \nفلو كان من بني عبد المطلب يبقى خلاص عرفنا، ولو كان حد تاني نطلب من رسول الله ﷺ إنه يوصيه بالخلافة لنا من بعده، فَقَالَ عَلِيٌّ: \n\"إنَّا واللَّهِ لَئِنْ سَأَلْنَاهَا رَسولَ اللَّهِ ﷺ فَمَنَعَنَاهَا لا يُعْطِينَاهَا النَّاسُ بَعْدَهُ، وإنِّي واللَّهِ لا أسْأَلُهَا رَسولَ اللَّهِ ﷺ\"\nيعني لو هو سأل رسول الله ﷺ إنه يوصى له بالخلافة ورفض، الناس هيرفضوا خلافة علي لو حصل وجه الوقت إللي يستحق يكون فيه خليفة بسبب رفض رسول الله ﷺ له، \nوهو  على كلِّ حَال لن يَسألَ النبيَّ ﷺ الإمارَةَ؛ لِأَنَّه أصلا مش عايزها وزاهد فيها.\nكان رسول الله ﷺ مش بس بيتألم من الحمى والصداع، ولكن كمان كان بيتألم من أثر السم إللي كان في الشاة المسمومة إللي المرأة اليهودية أهدتها له و أكل منها في فتح خيبر، واتكلمنا عنها في الجزء المائة وتسعة وثلاثين،\nقال للسيدة عائشة:\n\"يا عائشة، ما أزال أجدُ أَلَمَ الطعام الذي أكلتُ بخيبر، فهذا أوان وجدت انقطاع أَبْهُرِي من ذلك السُّم\"\nيعني السم إللي كان في الأكلة البسيطة إللي أكلها رسول الله ﷺ من الشاة المسمومة استمر موجود في جسمه الفترة دي كلها،\nلحد ما جاء أجل رسول الله ﷺ فحصلت الحمى بسبب السم ده، \nيعني يا جماعة السم كان موجود في الجسم وجهاز المناعة كان بيقاومه، \nلحد ما ربنا أراد إنه يقبض روح رسول الله ﷺ فأذِن إن السم يكون هو السبب في مرض رسول الله ﷺ إللي مات فيه عشان ينال درجة الشهادة زيادة في تكريمه ورفع درجته عند الله.\nفي يوم الإثنين الثاني عشر من شهر ربيع الأول للسنة الحادية عشرة للهجرة، صلى أبو بكر الصديق رضي الله عنه بالصحابة صلاة الفجر،\nوهم واقفين صفوف بيصلوا، رسول الله ﷺ رفع ستار باب الغرفة إللي بتطل على المسجد عشان يبص عليهم،\nكان بقاله ثلاثة أيام مشفهمش،\nفلما شافهم وهم واقفين صفوف ورا بعض منظمين كده تبسم رسول الله ﷺ من سعادته بيهم،\nرسول الله ﷺ شايف ثمرة عمله، ونتيجة جهده، \nتعبه خلال ثلاثة وعشرين عام لم يذهب هباء منثورا،\nرحلته كانت من البداية كانت مؤلمة، سواء من تكذيب أهل مكة له ووصفه بالكذب والسحر،\nوأذى عمه والمشركين ومجالس المحاورة مع أهل مكة عشان يقنعهم بالإسلام،\nأوتعذيب أصحابه وقتلهم، ووفاة أبناءه وزوجته، والهجرة وآلامها، وغزوة أحد ومقتل أصحابه، ورحلته للطائف،\nوغيرها وغيرها من الآلام، \nولكن العبرة بالنهاية، بعد الرحلة الطويييلة دي شايف الصحابة آمنين مطمئنين في صلاتهم بيصلوا زي ما علمهم،\nكده خلاص مبقاش في حاجة تانية يقدر يعلمها لهم، \nالدور الجاي عليهم عشان يستلموا القيادة ويوصّلوا إللي اتعلموه لأهل الأرض كلهم،\nلما رسول الله ﷺ رفع الستار وتبسم، الصحابة من شدة فرحتهم لما شافوا رسول الله ﷺ كانوا هيخرجوا من الصلاة، \nوحتى أبو بكر رضي الله عنه بدأ يرجع للوراء لأنه فكر إن رسول الله ﷺ جاي يصلي بيهم، \nلكن رسول الله ﷺ أشار إليهم إنهم يتموا الصلاة، وأنزل رسول الله ﷺ الستارة ودخل للبيت وقال:\nأيها الناسُ، أيُّما أحَدٍ من الناسِ، أو من المؤمنينَ، أُصيبَ بمصيبَةٍ فليَتَعَزَّ بمصيبتِهِ بي عن المصيبةِ التي تُصيبُهُ بغيرِي، فإن أحَداً من أُمَّتي لَن يُصابَ بمُصيبَةٍ بعدي أشَدَّ عليهِ من مُصيبتي\"\nيعني أي حد هتصيبه مصيبة فليخفف ويهون على نفسه المصيبة بإنه يتذكر مصيبته بي، لأن المصائب الصغيرة بتهون لو وضعت جنب مصائب كبيرة، ومفيش مصيبة هتصيب أي حد بعده هتبقى أعظم ولا أكبر من مصيبة موت رسول الله ﷺ،\nوزي ما قال الشاعر《أبو العتاهية》:\nاِصْبِرْ لِكُلِّ مُصِيبَةٍ وَتَجَلَّدِ   \nوَاعْلَمْ بِأَنَّ الْمَرْءَ غَيْرُ مُخَلَّدِ\nوَإِذَا أَتَتْكَ مُصِيبَةٌ تَشْجَى بِهَا \n《فَاذْكُرْ مُصَابَكَ بِالنَّبِيِّ مُحَمَّدِ》\nودي كانت آخر مرة رسول الله ﷺ يشوف الصحابة ويشوفوه،\nلما جاء وقت الضحى جاءت السيدة فاطمة تزور رسول الله ﷺ، وكان من عادته إنه لما يشوفها يقوم لها ويقبلها بين عينيها ويقعدها مكانه،\nوهي كمان كانت بتعمل كده، كان لما يأتيها كانت تقوم وتقبله بين عينيه وتقعده مكانها، \nفلما جاءته مقدرش يقوم لها ﷺ، لكنه رحّب بها وأجلسها بجانبه وقالها سر في ودنها فبكت بكاء شديد، وبعدين راح قايلها سر تاني فضحكت، \nفلما سألتها السيدة عائشة عن إللي رسول الله ﷺ قاله لها قالت لها:\n\"ما كنت أفُشِي على رسول الله ﷺ سرَّه\"\nولما شافت إن المرض اشتد على رسول الله ﷺ تألمت لمرض رسول الله ﷺ وقالت:\nوَاكَربَ أَبَتَاهُ! يعني بتتألم وتتأوه لمرض رسول الله ﷺ \nفقال لها رسول الله ﷺ:\n\"لَيْسَ عَلَى أَبِيكِ كَرْبٌ بَعْدَ الْيَوْمِ\"\nيعني خلاص بعد النهاردة مفيش ألم ولا وجع لأن رسول الله ﷺ لما يموت هيدخل الجنة.\n☆السيدة عائشة بعد موت رسول الله ﷺ سألت السيدة فاطمة مرة تانية عن السر إللي قاله لها رسول الله ﷺ فقالت لها إن رسول الله ﷺ قالها إنه هيموت وإنه قالها تصبر، فحزنت وقعدت تبكي،\nوبعد كده قالها:\nأمَا ترضِي أن تكوني سيدة نساء المؤمنين أو سيدة نساء هذه الأمة؟\nوقال لها إنها أول واحدة هتلحق بيه من أهله،\n فكان ده سبب ضحكها.\nوفعلا ماتت بعد رسول الله ﷺ بستة أشهر.\nاشتد المرض على رسول الله ﷺ واقتربت النهاية ومع ذلك كان يوصي أمته ويقول:\n\" الصلاة الصلاة، وما ملكت أيمانكم، الصلاة الصلاة، وما ملكت أيمانكم\"\nيعني الزموا الصلاة وأقيموها بالمحافظة عليها والمداومة على حقوقها، وأكد على وجوب مراعاة حقوق المملوك سواء كان إنسان أو حيوان.\nكان رسول الله ﷺ نايم وهو ساند رأسه على صدر عائشة رضي الله عنها وكان يتعرق بشدة وكان جنبه زي طبق كده فيه ماء، \nفكان يضع يده في الإناء ويمسح وجهه بالماء وهو يقول:\n\"لا إله إلا الله، إن للموت سكرات\"\nودخل عبد الرحمن بن أبي بكر الصديق أخو عائشة وكان معاه سواك، فنظر رسول الله ﷺ للسواك في يده،\nفعرفت السيدة عائشة إنه عايز السواك، فأخذت السواك من أخيها فمضغته وهيأته للاستعمال وأعطته لرسول الله ﷺ،\nفتسوّك به، وطهَّر أسنانَه بأحسَن صُورةٍ مُمكنَة،\nوبعدين رفع إيده عشان يرجّع السواك لعائشة فسقطت يده من شدة الضعف إللي كان فيه،\nفقعدت السيدة عائشة ترقيه بالرقية الشرعية، وهي بترقيه شافت بصره ينظر ناحية السماء وسمعته بيتمتم بكلمات فأصغت للكلام فسمعته يقول:\nمَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا ،\nاللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الأَعْلَى،\nاللَّهم الرفيق الأعلى، اللَّهم الرفيق الأعلى، اللَّهم الرفيق الأعلى\"\nوكان رسول الله ﷺ بيقول لهم قبل كده:\n \"إنه لم يُقْبَضْ نَبِىٌّ حتى يرى مقعده من الجنة ثم يُخَيَّر\"\nيعني مفيش نبي إلا وربنا يُريه مقعده من الجنة ثم يخيره ملك الموت بين الموت ودخول الجنة وبين إنه يعيش في الدنيا،\nفلما سمعته بيقول الكلام ده عرفت إنه تم تخييره واختار الموت ودخول الجنة،\nبعد ما قال رسول الله ﷺ:\n\"اللَّهم الرفيق الأعلى، اللَّهم الرفيق الأعلى، اللَّهم الرفيق الأعلى\"\nمالت يده ﷺ ومات رسول الله ﷺ.\nأعظم مصيبة ممكن تمر على الصحابة هي موت رسول الله ﷺ، إن شاء الله المرة الجاية هنشوف رد فعل الصحابة على المصيبة دي.\nمصادر جزء النهاردة في التعليقات"}, {"n": 260, "l": "الجزء 234 | رد فعل الصحابه  بعد موت رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وأربعة_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#رد_فعل_الصحابة_بعد_موت_رسول_الله\nوقفنا المرة إللي فاتت عند موت رسول الله ﷺ، تقول السيدة عائشة:\n\"مات رسولُ الله ﷺ بينَ سَحْرِي ونَحْرِي وفي دَوْلَتِي لم أَظلمْ فيهِ أَحَدًا،\nفمن سَفَهِي وحداثةِ سِنِّي أنَّ رسولَ اللهِ ﷺ قُبِضَ وهو في حِجْرِي، ثم وضعتُ رأسَهُ على وسادةٍ وقمتُ أندبُ مع النساءِ وأضربُ وجهي\"\nيعني بتقول إن رسول الله ﷺ مات وهو على صدرها وفي يومها وفي بيتها الذي لم تظلم فيه أحد،\nوبعدين وضعت رأس رسول الله ﷺ على مخدة وقامت تندب وتبكي وتلطم وجهها مع بعض النساء كانوا عندها،\nوطبعا الفعل ده محرم ولكن هي مكنتش تعرف إنه حرام ولا بعض الصحابيات إللي كانوا معاها يعرفوا بحرمانية إللي عملوه،\nوالدليل على كده إنها نَسبت فعلها للسّفه إللي هو الجهل، وكمان صغر السن،\nلأن السيدة عائشة كان عمرها ثمانية عشرة عام لما مات رسول الله ﷺ، وكان عمر رسول الله ﷺ لما مات ثلاثة وستين عام،\nوواضح من كلامها إنها تابت عن الفعل ده، \nالسيدة فاطمة لما مات رسول الله ﷺ قالت:\nيَا أَبَتَاهُ، أَجَابَ رَبًّا دَعَاهُ! يَا أَبَتَاهُ، جَنَّةُ الْفِرْدَوْسِ مَأْوَاهُ! يَا أَبَتَاهُ، إِلَى جبْرِيلَ نَنْعَاهُ! \n☆ملحوظة:\nالكلام إللي السيدة فاطمة قالته ده مش من النياحة؛ لأن النياحة هي رفع الصوت بالبكاء، والسيدة فاطمة معملتش كده،\nويجوز مخاطبة الميت إذا كان الكلام فيه، يعني مثلا نقول للميت:\nنرجو لك الخير عند الله، نرجو أن تكون من عباد الله الصالحين، أو لطالما كنت واصلاً للرحم، عاطفاً على الفقراء، متقرباً إلى الله، قواماً لليل، صواماً للنهار، وهكذا،\nأما إن الواحد يعرض مشاكله على الميت أو مشاكل الأمة مثلا فده غير جائز،\nيعني يقول:\nيا فلان نزلت بنا شدائد، ونزلت بنا كروب بعدك، ونزلت بنا مصائب، ونزلت بنا أمراض، ومات فلان، وتفرقت الأسرة و....و....كل ده لا يجوز.\nبدأ انتشار الخبر إن رسول الله ﷺ مات، فحصل اضطراب شديد في المدينة،\nوانقسم الصحابة بين مذهول وقف تفكيره، وبين إللي قعد في الأرض ومش قادر يقوم من شدة هَوْل الخبر،\nوبين إللي أنكر الخبر أصلا ولم يصدقه،\nفتنة وابتلاء عظيم، رسول الله ﷺ مات؟!\nإزاي يعني هنقدر نعيش من غيره؟\nهنصلي ورا مين؟\nمين إللي هينصحنا؟ \nمين إللي هيعلمنا ويربينا؟\nمين إللي هيتبسم في وجوهنا ويرفق بنا ويأخذ بأيدينا؟\nالواحد فيهم مكنش بيصبر على فراقه، كان مجرد ما يروح بيته إلا ويُسرع بالرجوع للمسجد عشان يشوفه،\nطيب دلوقتي هيشوفوه تاني إزاي؟\nالجذع حن لرسول الله ﷺ لما فارقه عشان يخطب من فوق المنبر لدرجة إن الصحابة سمعوا أنين الجذع،\nفإذا كان الجذع عمل كده ورسول الله ﷺ فارقه إلى منبر بعيد عنه خطوات معدودة فكيف بفراق لا رجعة فيه إلى يوم القيامة؟\nالموضوع كان مؤلم جدا على الصحابة، مهما حاولنا نوصف ألمهم مش هنقدر نعبر عنه،\nيعني احنا مجرد ما نسمع وفاة رسول الله ﷺ من غير ما نشوفه ونعيش معاه بنتأثر وبنتألم، فما بالكم بألمهم وهم إللي كانوا معاه على طول ولا يفارقوه\nالناس اجتمعوا في المسجد بيتكلموا وفي اضطراب حاصل، فوقف عمر بن الخطاب وفي إيده السيف وهو بيقول:\n\"إن رجالاً من المنافقين يزعمون أن رسول الله ﷺ قد مات واللَّهِ ما مَاتَ رَسولُ اللَّهِ ﷺ،\nلكن ذهب إلى ربه كما ذهب موسى بن عمران، فغاب عن قومه أربعين ليلة ثم رجع إليهم بعد أن قيل: قد مات،\nولَيَبْعَثَنَّهُ اللَّهُ، فَلَيَقْطَعَنَّ أيْدِيَ رِجَالٍ وأَرْجُلَهُمْ،\nيزعمون أنه مات،\nلَا يَتَكَلَّمْ أَحَدٌ بِمَوْتِهِ إِلَّا ضَرَبْتُهُ بِسَيْفِي هَذَا\"\nعمر بن الخطاب رضي الله عنه كان بيقول الكلام ده وهو معتقده يقينا ومعندوش أدنى شك في كده،\nيعني بيقول إن رسول الله ﷺ لم يمت فعلا،\nوإنه ذهب للقاء الله زي موسى عليه السلام لما ذهب للقاء الله وغاب عن بني إسرائيل أربعين ليلة،\nفأي حد هيقول إنه مات يبقى كده بيعمل فتنة بين المسلمين، وإنه مش هيسكت لأي حد يعمل الفتنة دي وهيضربه بسيفه،\nورسول الله ﷺ لما يرجع هيقطع أيدي وأرجل الناس إللي ادعت إنه مات وحاولت تعمل فتنة،\nفالناس سكتوا لأنهم مكنوش عارفين يعملوا إيه لأن مكنش في نبي قبل رسول الله ﷺ،\nرسول الله ﷺ لما كان بيوصف الصحابة كان بيقول عن عمر رضي الله عنه:\n\"وأشدهم في أمر الله عمر\"\nيعني كان هو أقواهُمْ في دِينِ اللهِ والحَقِّ، فتخيلوا إن ده أثر المصيبة على أشد الصحابة، فما بالكم باللي أقل منه،\nأنس بن مالك رضي الله عنه خادم رسول الله ﷺ بيلخّص لنا حال المدينة لما مات رسول الله ﷺ في كلمتين بيقول:\n\"لمَّا كانَ اليومُ الَّذي دخلَ فيهِ رسولُ اللَّهِ ﷺ المدينةَ أضاءَ منْها كلُّ شيءٍ، فلمَّا كانَ اليومُ الَّذي ماتَ فيهِ أظلمَ منْها كلُّ شيءٍ\"\nوقال:\n\"شَهِدْتُهُ يومَ دخلَ المدينةَ فما رأيتُ يومًا قطُّ كانَ أحسَنَ ولا أضوَأَ من يومٍ دخلَ علينا فيهِ رسولُ اللَّهِ  ﷺ،\nوشَهِدْتُهُ يومَ موتِهِ ، فما كانَ أقبحَ ، ولا أظلَمَ من يومٍ ماتَ فيهِ رسولُ اللَّهِ ﷺ\"\nيعني أنس بيقول كان حاضر في اليوم إللي دخل فيه رسول الله ﷺ المدينة وكان صغير في السن، \nفلما دخل رسول الله ﷺ  كل حاجة في المدينة أشرقت بالخيرِ والبرَكةِ، فكان أجمل يوم في حياتهم،\nأما اليوم إللي مات فيه فمكنش في يوم كان أكثَرَ إظلامًا من اليوم ده، وطُمِسَ عن المدينة نورُ النَّبيِّ ﷺ، والكلام ده كِناية عن عظيمِ حُزنِهم وغمِّهم بفَقْدِ رسول الله ﷺ.\nكل إللي بيحصل ده وأبو بكر رضي الله عنه غائب،\nكان في منطقة السُّنْحِ في أعالي المدينة؛ لأنه كان متزوج من حبيبة بنت خارجة، وكان تسكن في المنطقة دي وكان اليوم ده يومها،\nفكان بعد صلاة صبح يوم الاثنين لما شاف إن رسول الله ﷺ تحسّن، استأذن أبو بكر رضي الله عنه من رسول الله ﷺ إنه يروح لزوجته في السُّنْحِ لأن ده كان يومها فأذِن له رسول الله ﷺ،\nلما كان عمر واقف بيهدد الناس وهم قاعدين ساكتين قالوا لواحد منهم اسمه سالم بن عُبَيد الأشْجَعِي:\n\"يَا سَالِمُ اذْهَبْ إِلَى صَاحِبِ النَّبِيِّ ﷺ، فَادْعُهُ\"\nيعني روح لأبي بكر ونادي عليه عشان ييجي يشوف حل للموضوع ده،\nفخرج عشان يروح يناديه من السُّنْحِ لقاه جاء وواقف عند المسجد، فلما شافه سالم بدأ يبكي،\nفسأله أبو بكر:\nمَاتَ رَسُولُ اللهِ ﷺ؟\nفقال له سالم:\n\"إِنَّ عُمَرَ يَقُولُ: لَا يَتَكَلَّمُ أَحَدٌ بِمَوْتِهِ إِلَّا ضَرَبْتُهُ بِسَيْفِي هَذَا\"\nفوضع أبو بكر يده على ساعد يد سالم، إللي هي المنطقة بين الكوع ورسغ اليد، وبعدها دخل يمشي في المسجد فوسعوا له الطريق لحد ما دخل على رسول الله ﷺ،\nفوجد رسول الله ﷺ على فراشه قد غطوا وجهه، \nفكشف عن وجهه، وعرف إنه مات ﷺ،\nالواحد فينا لو تخيل إن في واحد من الصحابة ممكن يموت  حزنًا، وهمًّا، وكمدًا لفراق رسول الله ﷺ، فبدون شك هنقول الشخص ده هو أبو بكر رضي الله عنه؛\nلأنه أشد الخلق حبًّا لرسول الله ﷺ، وأقرب الرجال إلى قلب رسول الله ﷺ، \nوهو لم يكن رسولاً فقط بالنسبة له، لكنه كان صاحب وموطن سر، ومبشراً ومطمئناً، وزوجاً لابنته، ورئيساً لدولته، وهادياً لطريقه، كان كل شيء في حياة الصديق،\nواحنا شوفنا لما رسول الله ﷺ اتكلم عن تخيير الله لعبد من عباده بكى إزاي وتألم،\nوعمر القوي ده كان رد فعله أمال أبو بكر هيعمل إيه؟!\nلما عرف إن رسول الله ﷺ مات بكى رضي الله عنه بكاءا مراً، وقَبَّلَهُ بين عنيه وقَالَ:\n\"بأَبِي أنْتَ وأُمِّي، طِبْتَ حَيًّا ومَيِّتًا، والذي نَفْسِي بيَدِهِ لا يُذِيقُكَ اللَّهُ المَوْتَتَيْنِ أبَدًا\"\nوقال:\n\"إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ\"\nثم خرج أبو بكر رضي الله عنه من عند رسول الله ﷺ في ثبات عجيب يليق بخير الناس بعد رسول الله ﷺ،\nوكان الموقف كما هو، عمر واقف يقسم بالله أن رسول الله ﷺ لم يمت والناس حوله صامتين،\nفهنا قال له أبو بكر:\n\"أيُّها الحَالِفُ علَى رِسْلِكَ\"\nيعني على مهلك، شوف انت بتقول إيه، وبعدين قال له:\n\"اجْلِسْ يا عُمَرُ \"\nعشان يعني أبو بكر يعرف يتكلم، لكن عمر مش سامع أصلا ولا في وعيه ورفض إنه يقعد واستمر في الكلام،\nفالناس بدأوا يلتفوا حول أبي بكر وزير رسول الله ﷺ الأول وأحب الناس له،\nفتشهد أبو بكر رضي الله عنه وحمد الله وأثنى عليه وهنا سكت عمر وبدأ يسمع لأبي بكر، قال أبو بكر:\n\"أَلا مَنْ كَانَ يَعْبُدُ مُحَمَّدًا ﷺ فَإِنَّ مُحَمَّدًا قَدْ مَاتَ، وَمَنْ كَانَ يَعْبُدُ اللَّهَ فَإِنَّ اللَّهَ حَيٌّ لاَ يَمُوتُ\"\n☆كلام أبي بكر كان فيه فهم عميق وحكمة بالغة، فهو بيضع الأمور في حجمها الطبيعي، \nأيوة المصيبة عظيمة لكن مينفعش أبداً إن المسلمين يخرجوا عن شعورهم وعن حكمتهم وعن إيمانهم بسببها، \nبيوضح لهم الحقيقة إللي غابت عنهم وهي إن رسول الله ﷺ بشر،\nوكل البشر يموتون، واحنا مكناش بنعبد رسول الله ﷺ \nولكننا جميعاً عبدنا معه رب العالمين سبحانه وتعالى، \nوالله حي لا يموت، \nفلا داعي لاختلاط الأمور، ولا داعي للفتنة، ولا داعي للاضطراب، وإللي حصل ده أمر متوقع، \nوربنا هو إللي هيجزينا على صبرنا أو يعاقبنا على جزعنا\nوبعدين قرأ عليهم أبو بكر آية تذكرهم وتبصرهم بالحقيقة إللي غفلوا هنا ونسيوها وإللي بتؤكد كلامه، قال:\n\"وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ أَفَإِنْ مَاتَ أَوْ قُتِلَ انْقَلَبْتُمْ عَلَى أَعْقَابِكُمْ وَمَنْ يَنْقَلِبْ عَلَى عَقِبَيْهِ فَلَنْ يَضُرَّ اللَّهَ شَيْئًا وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ\"\nيقول عبد الله بن عباس:\n\"واللَّهِ لَكَأنَّ النَّاسَ لَمْ يَعْلَمُوا أنَّ اللَّهَ أنْزَلَ هذِه الآيَةَ حتَّى تَلَاهَا أبو بَكْرٍ،\nفَتَلَقَّاهَا منه النَّاسُ كُلُّهُمْ، فَنَشَجَ النَّاسُ يَبْكُونَ، فَما أسْمَعُ بَشَرًا مِنَ النَّاسِ إلَّا يَتْلُوهَا\"\nيعني الناس من صدمتهم كانوا ناسيين إن ربنا أنزل الآية دي لحد ما قرأها عليهم أبو بكر،\nمع إنها نزلت بعد غزوة أحد، لكن من هول المصيبة نسيوا الآية، وأول ما تذكروها كل واحد فيهم بدأ يقولها وهو بيبكي وكأنهم بيهونوا على أنفسهم بعد ما تيقنوا إن خلاص رسول الله ﷺ مات،\nأما عمر فاندهش من كلام أبي بكر ورجله سابت من بعضها ومبقاش قادر يقف فانهار وسقط على الأرض وعرف كده إن رسول الله ﷺ مات،\nأبو بكر رضي الله عنه ربنا ثبت بيه أمة كادت أن تضل، وأوشكت أن تُفتن،\nولو لم يكن له من المواقف في الإسلام إلا هذا الموقف لكان كافياً\nفاللي أخبر الصحابة بموت رسول الله ﷺ هو أبو بكر الصديق رضي الله عنه وليس السيدة عائشة زي ما هو منتشر بين الناس إن لما سول الله ﷺ مات السيدة عائشة فتحت الستارة إللي بتطل على المسجد وقالت لهم إن رسول الله ﷺ مات،\nالكلام ده غير صحيح نهائي، أبو بكر رضي الله عنه هو إللي أخبر الصحابة بموت رسول الله ﷺ\nوارتفع البكاء في المدينة، لدرجة إن واحد من المسلمين اسمه \nأبو ذؤيب الهذلي رضي الله عنه قال:\nقَدِمتُ المدينة ولأهلها ضجيج بالبكاء، كضجيج الحجيج أهلّوا جميعاً بالإحرام،\nيعني هو جاء للمدينة في يوم موت رسول الله ﷺ فسمع أصوات بكاء أهل المدينة زي ما الحجاج لهم صوت وهم بيهلّوا للإحرام،\nفسأل: ماذا حصل؟ فقالوا له: \nقُبض رسول الله ﷺ.\nوفاة رسول الله ﷺ كانت فتنة ومصيبة عظيمة، لكن مكنتش دي هي الفتنة الوحيدة إللي واجهت الصحابة،\nيا ترى إيه الفتن إللي هيواجهوها تاني؟\nده إللي هنعرفه الجزء الجاي إن شاء الله.\nمصادر جزء النهاردة في التعليقات"}, {"n": 261, "l": "الجزء 235 | احداث السنه الحادية عشرة من الهجرة | الفتن بعد موت رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وخمسة_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#الفتن_بعد_موت_رسول_الله\nاتكلمنا المرة إللي فاتت عن رد فعل الصحابة على موت رسول الله ﷺ وقلنا إن مش دي الفتنة الوحيدة إللي الصحابة تعرضوا لها،\nرسول الله ﷺ كان بيقول لهم:\n\"النُّجُومُ أَمَنَةٌ لِلسَّمَاءِ، فَإِذَا ذَهَبَتِ النُّجُومُ أَتَى السَّمَاءَ ما تُوعَدُ، وَأَنَا أَمَنَةٌ لأَصْحَابِي،\n فَإِذَا ذَهَبْتُ أَتَى أَصْحَابِي ما يُوعَدُونَ، وَأَصْحَابِي أَمَنَةٌ لِأُمَّتِي، فَإِذَا ذَهَبَ أَصْحَابِي أَتَى أُمَّتي ما يُوعَدُونَ\"\nيعني النجوم، طول ما هي موجودة في السماء فده معناه استمرار وجود السماء، \nأول ما النجوم تسقط من السماء يوم القيامة ستضعف السماء وتنشق وينتهي وجود السماء إللي احنا عارفينها؛\nلأن ربنا قال:\n\"يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ\"\nفكأن النجوم زي الحرّاس كده بتحرس السماء، أول ما الحارس يمشي من مكان حراسته بتحصل الأمور إللي كان مانعها وجود الحارس،\nسواء بقى سرقة أو هجوم على المكان أو ...أو...\nفرسول الله ﷺ هو حارس لأصحابه مِنَ الفِتَنِ والحروبِ وارتدادِ مَنِ ارْتَدَّ مِنَ الأعرابِ واختلافِ القلوبِ وغيرها من الأمور إللي رسول الله ﷺ حذرهم منها،\nفلما يموت رسول الله ﷺ هتبدأ الفتن والحروب، \nوالصحابة هم حراس الأمة،\nإذا ذهبوا يعني ماتوا دخلت البِدعِ والحوادثِ والفِتَنِ في الدِّينِ على الأمة، وده حصل فعلا في الأجيال إللي كانت بعد الصحابة، واحنا شايفين ده حاصل فعلا في زمننا احنا على الأقل\nفوجود رسول الله ﷺ كان أمان للصحابة، لكن رسول الله ﷺ مات دلوقتي فبدأت أول فتنة وهي:\n◇فتنة انقطاع الوحي:\nجبريل عليه السلام لن ينزل على بشر إلى يوم القيامة؛ رسول الله ﷺ هو خاتم الأنبياء، \nولا شك أن البشر هيقعوا كثيرا في الخطأ وهيحتاجوا إلى تقويم وإصلاح، فمين إللي هيعمل التقويم ده؟ \nلازم هم إللي يصلحوا الأخطاء بتاعتهم، فلاشك إن الفترة دي بعد موت رسول الله ﷺ كانت عِبئ ثقيل على نفوس الصحابة، وعندهم قلق شديد من إنهم يفشلوا في حل أمورهم دون وحي،\nمع إن المنهج الإسلامي المتكامل جعل لهم أساسيات يمشوا عليها عشان يكملوا مسيرة الحياة إلى يوم القيامة بدون رسل ولا أنبياء ولا وحي، \nوأكيد طبعا هيختلفوا، لكن المشكلة هتكون مين إللي هيكون على صواب؟ ومين إللي هيكون على خطأ؟\nمين إللي اجتهاده صح؟\nطبيعي إن طوائف من المؤمنين تُخطئ وهي تظن أنها على صواب كطبيعة البشر،\n ده لسه كانوا مختلفين قبل موت رسول الله ﷺ بأيام لما طلب منهم إنهم يأتوه بكتاب يكتبه لهم،\nوالوحي كان بيفصِل في الأمور دي وينهيها، لكن الآن انقطع الوحي،\nهيعملوا إيه بقى في الأحداث الجاية المُستجدة وإللي لم يواجهوا زيها قبل كده؟\nوالرجل في زمن رسول الله ﷺ كان يسير على الأرض، وهو يعلم أنه من أهل الجنة،\nوبيبقى عنده يقين بكده إذا بشره رسول الله ﷺ،\nزي ما رسول الله ﷺ أخبر بلال وأبو بكر وعمر وغيرهم إنهم من أهل الجنة،\nلكن دلوقتي بعد ما انقطع الوحي فلا أحد يدري أهو من أهل الجنة أم من أهل النار،\nرسول الله ﷺ كان يُخبرهم عن كثير من أمور الغيب بالوحي، فبشرهم بنصر بدر، وبشرهم بالفتح، وبشرهم بفتح الشام وفارس واليمن، \nوكان يُخبرهم عن إللي هيحصل في المستقبل إلى يوم القيامة، لكن دلوقتي بعد انقطاع الوحي أغلب باب المستقبل لا نعرف منه إلا ما أنبأنا به رسول الله ﷺ قبل ما يموت، \nلكن كم من الأمور ستحدث كنا نتمنى أن نعرف عاقبتها،\nهل يا ترى سنفوز أم سنخسر، وأحداث العالم نتيجتها هتكون إيه في النهاية،\nأيوة رسول الله ﷺ ترك لنا منهج واضح من قرآن وسنة نستقرئ به سنن الله في الأرض، ونستنبط به النتائج قبل ما تحصل،\nلكن منعرفش الأمور على وجه اليقين زي ما كان رسول الله ﷺ موجود،\nيعني مثلا ربنا كان أنزل:\n\"غُلِبَتِ الرُّومُ ۩ فِي أَدْنَى الأَرْضِ وَهُمْ مِنْ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ۩ فِي بِضْعِ سِنِينَ\"\nفالوحي كان حدد بالضبط بعد كم سنة الروم هتغلب الفرس، فاحنا مثلا في عصرنا دلوقتي المسلمين مستضعفين في كل مكان، \nحد يقدر يقول خلال مثلا كذا سنة المسلمين هينتصروا ويسودوا الدنيا؟\nلأ محدش يقدر، أيوة المسلمين فعلا هيحكموا الأرض في زمن من الأزمنة لكن منعرفش امتى بالضبط،\nفالشاهد من الكلام إن احنا نقدر نعرف الكثير من الأمور على وجه الظن لا على وجه اليقين، \nويقين الوحي غير موجود حتى تنتهي حياة الأرض وتقوم القيامة\nوالكلام ده هياخدنا للفتنة الثانية إللي واجهت الصحابة بعد موت رسول الله ﷺ وهي:\n◇مين إللي هيحكم المسلمين بعد رسول الله ﷺ؟\nالوحي منقطع دلوقتي، هنختار خليفة وحاكم للمسلمين إزاي ومفيش وحي يوجهنا؟\nطيب نفرض إن اختيارنا كان غلط هنعرف إزاي؟\nفهم هنا لازم يجتهدوا ويجمعوا نصوص الوحي جنب بعضها عشان يقدروا يطلعوا بقرار سليم،\nوالفتنة دي خطيرة عليهم مش بس لأن في احتمال التنازع  على السلطة زي ما بيحصل في بلدان العالم المختلفة إذا مات قائد أو زعيم، لأ، \nالخطورة هنا لاعتبارات خاصة جداً بالفترة دي:\n¤أولا:\n لا يوجد في الصحابة ولا في أهل الأرض جميعاً مَن يساوي أو يقترب في الفضل من رسول الله ﷺ، \nوالشخص إللي هيكون في مكان رسول الله ﷺ كحاكم أكيد هيحصل مقارنة بينه وبين رسول الله ﷺ كطبيعة البشر،\nولو حصلت المقارنة فلا شك إنها هتكون مقارنة ظالمة،\n فهذا رسول يُوحى إليه من ربه وأدّبه ربه، وهذا رجل يجتهد قد يصيب وقد يخطئ، فاحنا محتاجين واحد له مواصفات خاصة جدا.\n¤ثانيا:\nمين من الصحابة ستطيب نفسه أن يجلس في مكان رسول الله ﷺ؟\nوالصحابة على خلاف أهل الأرض في زماننا أو في أي زمان كانوا لا ينظرون إلى الإمارة على أنها تشريف وتعظيم أبداً،\nولكن كانوا يعتبرونها تكليفاً ومشقة، \nفغير إنهم لا تطيب نفسهم بالحكم بدل من نبيهم؛ فهم تعلموا من رسول الله ﷺ أن يزهدوا في الإمارة ولا يطلبوها،\nهم عارفين كلام رسول الله ﷺ إللي قاله لأبي ذر:\n\"يَا أَبَا ذَرٍّ، إنَّكَ ضَعِيفٌ، وإنَّهَا أَمانةٌ، وإنَّها يَوْمَ القيامَة خِزْيٌ ونَدَامةٌ، إلَّا مَنْ أخَذها بِحقِّها، وَأدَّى الَّذِي عليهِ فِيها\"\nفمين من الصحابة يضمن أن يأخذها بحقها؟ \nومين منهم يعرض نفسه لحمل الأمانة؟ \nومين منهم يضع نفسه يوم القيامة موضع سؤال عن تبعات عظيمة من أجل الإمامة؟\n¤ثالثا:\nإذا كان ولابد أن يختاروا رجل من الصحابة لهذا الأمر العظيم  فمن يكون هذا الرجل؟\nكل الصحابة عظماء يُقتدى بهم، وطاقاتهم عظيمة، وإمكانياتهم واسعة، والمُؤَهل ليكون حاكماً على الناس أو أميراً عليهم عددهم كثير، معظم الصحابة تقريبا ينفع يكونوا في موضوع الحكم،\nعندنا من المهاجرين الصديق أبو بكر وعندنا الفاروق عمر، وعندنا ذو النورين عثمان،\nوعندنا علي إللي رسول الله ﷺ قال عنه رجل يحبه الله ورسوله ويحب الله ورسوله،\nعندنا أمين الأمة أبو عبيدة عامر بن الجرّاح، وعندنا الزبير بن العوام حواري رسول الله ﷺ، \nوعندنا شيوخ مكة إللي أسلموا حديثا ولهم مكانة ومهابة عند العرب زي أبو سفيان وسهيل بن عمرو،\nوعندنا من الأنصار سعد بن عبادة سيد وزعيم الخزرج، وعندنا أسيد بن حضير من الأوس إللي الملائكة كانت بتسمع له وهو بيقرأ القرآن،\nوغيرهم وغيرهم من الصحابة،  \nفالموضوع كان صعب ومحير جدا، واحنا هنشوف المحاورات إللي حصلت بينهم عشان يختاروا الخليفة وإزاي إن كل واحد فيهم من وهو  بيعرض وجهة نظره والأدلة إللي معاه هتحسوا إنه كان معاه الحق.\n◇ثالث فتنة هتواجه الصحابة هي الأعداد المهولة إللي كانت دخلت في الإسلام حديثاً ومكنتش اتربت من رسول الله ﷺ زي ما اتربى باقي الصحابة في المدينة،\nيعني هم ارتبطوا بالإسلام من كم شهر بس، ولم يسمعوا من رسول الله ﷺ إلا الكلمات القليلة، \nوفي بعضهم لم يره أصلاً، وبعضهم دخل لأجل المال، وبعضهم دخل لأجل الخوف من القوة الإسلامية الناشئة، وكلهم حديث عهد بجاهلية وإشراك،\nكل العوامل دي وغيرها خلتهم على خطر عظيم وبالذات إذا وصل لهم نبأ وفاة رسول الله ﷺ،\nيا ترى رد فعلهم هيكون إيه؟\nهل هيشككوا في أمر الرسالة؟\nهل هيفكروا إن الخروج عن جماعة المسلمين بقى أمر سهل وميسور؟\nهل هيرتدوا على أعقابهم ويعودون إلى جاهليتهم وشركهم؟\nكل دي احتمالات واردة، \nومتنسوش مسيلمة الكذاب إللي كان اتبعه أهل اليمامة بعد ما ارتدوا لما قال لهم إنه نبي،\nفمش بعيد ناس تانية تتبعه، ومش بعيد ناس تانية تطلع تدعي النبوة،\nوكان عدد الناس إللي اتبعوا مسيلمة الكذاب لوحده أربعين ألف من مشركي العرب، \nفالمرتدون دول أكيد متربصين بالمدينة ومستنيين أي فرصة للهجوم على المدينة وغزوها والقضاء على الإسلام تماما.\nضيفوا بقى للي احنا قلناه ده كله المنافقين إللي في المدينة،\nومحاولتهم هدم الإسلام من الداخل ومحاولتهم لقتل رسول الله ﷺ وهو راجع من تبوك ولكنهم فشلوا،\nودلوقتي الفرصة جاءت لهم، رسول الله ﷺ مات، فأكيد سعادتهم لا توصف دلوقتي،\nفيا ترى بقى المنافقين دول هيعملوا إيه؟\nومتنسوش إن في وسط الفتن المحيطة بالصحابة دي كان في ناس تانية كارهة للإسلام ووجوده ومترقبين هيحصل إيه لدولة الإسلام زي دولة فارس والروم،\nالمسلمين أذاقوا الرومان مرار الهزيمة في مؤتة وفي تبوك، واليمن إللي كانت تحت حكم الفرس بقت في أيدي المسلمين،\nفياترى بقى كسرى ملك الفرس وهرقل ملك الروم هيعملوا إيه في المسلمين دلوقتي؟\nطيب واليهود بقى هيسكتوا مثلا؟\nالعداء بين المسلمين واليهود قائم ولن ينتهي إلى قيام الساعة، ربنا بيقول:\n\"لَتَجِدَنَّ أَشَدَّ النَّاسِ عَدَاوَةً لِلَّذِينَ آمَنُوا الْيَهُودَ وَالَّذِينَ أَشْرَكُوا\"\nوهم بيكيدوا للإسلام والمسلمين من أول يوم ظهر فيه رسول الله ﷺ،\nفما بالكم بقى دلوقتي وهو خلاص مات؟\nأيوة تم قتل يهود بني قريظة قبل كده، وأخرج رسول الله ﷺ بني قينقاع وبني النضير من المدينة،\n لكن لسه يهود خيبر موجودين وهم مش مجموعة بسيطة وعايشين في حصونهم في شمال المدينة،\nفهل هينقضوا العهد ويدبروا مؤامرة ضد المسلمين، وخصوصا إنهم اشتهروا بنقض العهود وبالتعامل بالخيانة والكيد والتآمر، \nواشتهروا في وقت ضعفهم بالذلة والمسكنة والخنوع والنفاق،\nواشتهروا في وقت قوتهم بالإفساد في الأرض والتدمير والتخريب،\nوانتم شايفين اليهود بيعملوا إيه في زماننا دلوقتي من تخريب وإفساد وتدمير\nوضيفوا فوق كل ده إن رسول الله ﷺ كان أمر إن جيش أسامة يخرج للمكان إللي كان أمره به،\nيعني حتى القوة الوحيدة المستعدة للقتال والدفاع عن المدينة دلوقتي رسول الله ﷺ أمر إنها تخرج وتروح تقاتل في مكان تاني،\nكل الأحداث دي الصحابة كانوا بيفكروا فيها مع ألمهم وحزنهم على موت رسول الله ﷺ،\nالموقف كان صعب ومعقد ومُحزن جدا بعد موت رسول الله ﷺ،\nوالله يا جماعة الواحد دماغه لفت من مجرد التفكير بس في الأحداث دي كلها، أمال هم بقى إللي كانوا عايشين فيها يعملوا إيه ويخرجوا منها إزاي\nخلونا كده نلخص الفتن دي في عشر نقط سريعة:\n◇أولاً: \nمات أحب الخلق إلى قلوب الصحابة، وفراقه مصيبة.\n◇ثانياً: \nانقطع الوحي بالكلية إلى يوم القيامة.\n◇ثالثاً: \nليس هناك من يُقارب رسول الله ﷺ في الفضل حتى يستبدله الناس به.\n◇رابعاً: \nالأسماء المطروحة لخلافة رسول الله ﷺ كثيرة وكلها عظيمة.\n◇خامساً: \nوجود أعداد كبيرة جداً من الناس لم تدخل الإسلام إلا منذ سنوات أو شهور قليلة، وكثير منهم من المؤلفة قلوبهم وضعيفي الإيمان.\n◇سادساً: \nالرّدة الخطيرة الموجودة في بني حنيفة بقيادة مسيلمة الكذاب.\n◇سابعاً: \nكثرة المنافقين بالمدينة وتربصهم الدوائر بالمسلمين.\n◇ثامناً: \nدولة الفرس المُعادية تلتصق حدودها بالدولة الإسلامية من جهة الشرق وممكن تغزوها.\n◇تاسعاً: \nدولة الروم المُعادية هي كمان تلتصق حدودها بالدولة الإسلامية من جهة الشمال، والأحداث إللي قبل كده توحي بلقاء حربي قريب.\n◇عاشراً:\n اليهود في خيبر تغلي قلوبهم من الحقد على المسلمين وخيانتهم وشيكة.\nكل واحدة من الفتن العشرة دول ممكن لوحدها تعصف بدولة الإسلام، فما بالكم بيهم كلهم مجتمعين؟\nومتنسوش إن أمة بني إسرائيل إللي هي شبيهة بأمة الإسلام عبدوا العجل لمجرد إن موسى عليه السلام غاب عنهم أربعين ليلة وكان معاهم هارون عليه السلام،\nفدلوقتي الكل هيعلم إن رسول الله ﷺ خلاص مات، فيا ترى كم واحد هيقلد بني إسرائيل في فعلتهم الشنيعة؟\nيا ترى الصحابة هيتعاملوا مع الفتن دي إزاي، وإيه أول خطوة هيعملوها عشان يقدروا يحلوا المشاكل دي؟\nده إللي هنعرفه الجزء الجاي إن شاء الله.\nمصادر جزء النهاردة في التعليقات"}, {"n": 262, "l": "الجزء 236 | اجتماع الأنصار. في سقيفة بني ساعدة", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وستة_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#اجتماع_الأنصار_في_سقيفة_بني_ساعدة\nاتكلمنا المرة إللي فاتت عن الفتن إللي واجهت الصحابة بعد موت رسول الله ﷺ،\nوالمدينة كانت في حالة حزن شديد وقلق واضطراب، زي كده لما يكون في سفينة ماشية في بحر عاصف والأمواج تقذفها من هنا لهنا وفجأة يموت قبطان السفينة،\nفي الموقف الرهيب ده الناس إللي على السفينة هتنجوا إزاي؟\nفالحل الوحيد والسريع للنجاة إننا نشوف قبطان تاني عشان يقدر يقود السفينة عشان السفينة متغرقش،\nفكذلك الوضع بالنسبة للمدينة، عايزين نختار قائد بسرعة عشان يقدر يجمع كلمة المسلمين ويقدر ياخد قرارات عشان نواجه بيها الفتن المختلفة،\nوخصوصا إن رسول الله ﷺ كان قال لهم قبل كده:\n\"إذا خرجَ ثلاثةٌ في سفَرٍ فليؤمِّروا أحدَهُم\"\nيعني لو خرج مجموعة مع بعض مسافرين سواء كانوا ثلاثة أشخاص أو أكثر فلازم يكون للمجموعة دي قائد هو إللي ياخد القرارات بعد ما يشاور أصحابه،\nزي اختيار وَقْتِ الذَّهابِ والبَياتِ وغيرها من أحوالِ السَّفَرِ،\nفتخيلوا إن ده في أمر سفر فما بالكم بحاجة أعظم وهي اختيار قائد للأمة،\nفرسول الله ﷺ هنا بيشجع المسلمين على تقليل الخلاف بينهم وتوحيد كلمتهم بقدر الإمكان\n☆وده أمر عام في كل حياة المسلمين؛ لأنهم إذا اجتمعوا على رجل كانت البركة والقوة، وإذا تفرقوا كان الفشل والضعف،\nوانتم شايفين حال المسلمين دلوقتي وضياعهم بسبب إن مفيش خليفة يجمعهم كلهم\nفالصحابة أفضل أهل الأرض بعد الأنبياء وخير قرون أمة الإسلام كانوا عارفين خطورة الموضوع وإن مينفعش يكون في أي تأخير في اختيار الخليفة مهما كان اسمه،\nفعلى الرغم من كل الأحزان والهموم والآلام إللي هم فيها إلا إن الحياة لازم تمشي،\nوهو ده إللي رسول الله ﷺ علمه للصحابة خلال السنين إللي فاتت دي كلها، \nعلمهم معنى الصبر الجميل، الصبر الذي لا شكوى فيه، الصبر عند الصدمة الأولى،\nوده لما مرّ بامرأة تبكي عند قبر فقال لها:\nاتقي الله واصبري. \nفقالت له وهي متعرفش إنه رسول الله ﷺ:\n إليك عني؛ فإنك لم تصب بمصيبتي.\nيعني بالبلدي كده: انت مش حاسس بي وبمعاناتي فمتنصحنيش بالصبر، إللي إيده في المية مش زي إللي إيده في النار،\nفقيل لها: \nإن إللي انتِ كلمتيه ده رسول الله ﷺ فأتت باب النبي ﷺ فلم تجد عنده بوابين، يعني مكنش في حد يمنعها من مقابلة رسول الله ﷺ وده من تواضعه ﷺ بعكس عامة الحكام والملوك، فقالت له: \nلم أعرفك. يعني معلش إني رديت عليك كده ومأخذتش بنصيحتك أنا مكنتش أعرفك،\nفقال لها رسول الله ﷺ: إنما الصبر عند الصدمة الأولى.\nيعني أول ما يجيلك الخبر بحاجة تحزنك أو بمصيبة لازم تصبر ولو مصبرتش يبقى انت لا تدخل في الصابرين ولا تاخد أجر الصبر على المصيبة\nوعلمهم كمان بطريقة عملية بإنه كان قدوة في الصبر لما قُتل عمه حمزة وباقي شهداء أحد،\nالحياة استمرت على الرغم من كل الآلام إللي اتعرضوا لها،\nولما أبناؤه وبناته ماتوا ﷺ الواحد ورا التاني الدنيا موقفتش واستمرت الحياة وحادثة بئر معونة وماء الرجيع وغيرها وغيرها من المواقف المؤلمة، \nفكان رسول الله ﷺ مثال قصادهم إن مهما كانت الآلام والأحزان مينفعش حياتنا ودعوتنا تقف،\nفاحنا لما نفهم الكلام ده كويس هنفهم ليه الأنصار رضي الله عنهم  سارعوا للاجتماع في مكان اسمه ثَقِيفة بني ساعدة عشان يختاروا خليفة في نفس يوم موت رسول الله ﷺ حتى قبل ما يدفنوه\n¤وأنا بقولكم الكلام ده عشان في ناس بتطعن في الأنصار وبتتهمهم إنهم مكنوش زعلانين على موت رسول الله ﷺ وكان همهم الحكم وكلام كتير كده\nفعشان لو سمعتوا الكلام ده في أي مكان ومعرفتوش تردوا على الأقل تبقى قلوبكم مطمئنة إن الأنصار رضي الله عنهم كانوا غير كده تماما،\nوإنهم كانوا على الرغم من حزنهم إلا إن كان همهم الأكبر هو مصلحة الأمة، وكانوا وماشيين على نفس منهج رسول الله ﷺ بالضبط\n☆إيه بقى إللي حصل في سَقِيفة بني ساعدة؟\nأولا كده سَقِيفة بني ساعدة هي الدار إللي كانوا متعودين يجتمعوا فيها عشان يعقدوا فيها اجتماعاتهم المهمة،\nزي ما بنسميها في عصرنا كده قاعة اجتماعات، وزيها دار الندوة إللي قريش كانوا بيجتمعوا فيها في مكة واتكلمنا عليها قبل كده،\nفاجتمع الأنصار إللي هم الأوس والخزرج في السقِيفة عشان يختاروا خليفة 《منهم》 عشان يقدر يقود الأمة وسط الفتن إللي هيواجهوها\n◇طيب ليه الأنصار رضي الله عنهم كانوا شايفين إن الخليفة لازم يكون 《منهم》 بالذات؟\nوكمان ليه أسرعوا في اختيار الخليفة منهم من غير ما يرجعوا للمهاجرين، هل ده معناه إنهم كانوا عايزين ياخدوا الخلافة لنفسهم فقط؟\nخلونا كده نفكر مع الأنصار،\n◇أولا:\nهمّ الأنصار دول مين أصلا؟\nمش الأنصار دول هم الأوس والخزرج أهل البلد الأصليين؟ يعني خلونا نتكلم بمصطلحات زماننا دلوقتي،\nالمدينة دي كانت في الأصل دولة مستقلة اسمها يثرب فيها سكانها الأصليين إللي عايشين فيها،\nفتعرّض رسول الله ﷺ وأصحابه للاضطهاد في بلدهم إللي هي مكة، \nفحصل إن رسول الله ﷺ وإللي معاه هاجروا للمدينة، فأصبحوا بلغة عصرنا الحديث اسمهم لاجئين،\nوالمدينة كدولة كريمة سخية عادلة استقبلت اللاجئين أو المهاجرين خير استقبال وأكرمتهم وأعطت لهم ومنحتهم كل حقوق المواطن الأصلي في البلد، \nومرت الأيام ولم تفرض عليهم أبداً قيوداً تعوق من حياتهم، بل على العكس، كثيراً ما آثرتهم على أهل البلاد الأصليين،\nحلو كده\nمرت الأيام ومات قائد المدينة وزعيمها النبي محمد ﷺ وجاء وقت تولية زعيم جديد على المدينة، \nفبالعقل كده، هل من المنطق إن زعيم الدولة يكون من أهلها الأصليين أم من اللاجئين إليها؟ \nوهل من المنطق البسيط إن زعيم الدولة يكون من الناس إللي قدموا وبذلوا كل شيء للناس إللي جاءت لهم لاجئين،\nولّا يختاروا من إللي جاء طريداً من بلده واستقبلوه عندهم؟\nخلونا نقرب المعنى أكثر بمثال من الواقع،\nلو هاجر مجموعة من الفلسطنيين أو السوريين أو...أو... إلى أمريكا أو إنجلترا أو حتى إلى بلد إسلامي مجاور، \nهل يجوز في عرف هذه البلاد أنه إذا مات رئيسها أن يختار الرئيس الجديد من بين اللاجئين السياسيين إلى هذه البلد؟\nعلى حد علمي مفيش بلد عندها قانون بيسمح للاجئين إنهم يصعدوا إلى كرسي الحكم في البلد المُضيف\nفطبيعي إن إللي يحكم هم أهل البلد الأصليين،\nفهو ده إللي فكر فيه الأنصار من باب المسؤولية،\nفهم أصحاب البلد وأكثريتها ومُلاكها، والأرض أرض آبائهم وأجدادهم،\nفعلى أي أساس واحد تاني غيرهم من خارج البلد هو إللي يحكم\n \nطبعا وضع رسول الله ﷺ كحاكم كان مختلف مع إنه مش من أهل البلد الأصليين؛ لأنه كان نبي وكان طبيعي إن الأنبياء همّ إللي يحكموا قومهم؛ لأن الشريعة إللي جاء بها النبي هي إللي بتحكم\n◇ثانياً:\nأهل المدينة أدرى بالمدينة من أي حد تاني،\nوالمدينة هي دار الإسلام الرئيسية ومكة والطائف وغيرها ما هي إلا مدن تابعة لها،\nيبقى من المنطقي إن الأنصار يعتقدوا إنه من المصلحة إن إللي يقود دولة الإسلام هو أكثر حد عارف بوضعها وبسكانها وبالقبائل المحيطة بها وبتاريخها وجذورها،\nفكده من باب المصلحة إن قائد المدينة يكون من أهل المدينة نفسها \n◇ثالثاً: \nهل كان من الممكن إن المهاجرين يقدروا يُقيموا دولة من غير مساعدة الأنصار؟\nيعني المهاجرين قعدوا ثلاثة عشرة سنة في مكة ومعرفوش يحولوها إلى بلد إسلامي،\nفكان لابد من الهجرة لحد ما يوصلوا للقوة الكافية إللي تساعدهم في تحويل مكة لبلد إسلامي بعدين زي ما شوفنا،\nورسول الله ﷺ عرض نفسه على القبائل عشان يلاقي إللي ينصره ويؤويه هو وأصحابه زي ما شوفنا قبل كده،\nلحد ما بايع الأنصار على نصرة رسول الله ﷺ،\nفبدون الأنصار مكنش هيبقى في حاجة اسمها دولة الإسلام إلا لو كان في ناس تانية ممكن تقبل إللي الأنصار قبلوه،\nعشان كده كان من الطبيعي للأنصار إنهم يشعروا إنه من المنطقي أن يكون الرئيس الجديد من بينهم\n◇رابعاً: \nالأنصار كان عندهم إحساس إن المهاجرين هيرجعوا إلى بلدهم الأصلي مكة بعد وفاة رسول الله ﷺ، \nومكة هي البلد الحرام، وهي التي تركوا فيها ديارهم وأرضهم وأموالهم إللي صادرها المشركون، \nودلوقتي أسلم المشركون وبقى من حق المهاجرين إنهم يرجعوا لبلدهم ويسترجعوا حقوقهم إللي أُخذت منهم قهرا،\nومن حقهم إنهم يعيشوا في البلد الحرام إللي الصلاة فيه بـ مائة ألف صلاة،\nومن حقهم أن يعودوا للذكريات الأولى، والعائلات الأصيلة في مكة وما حولها،\nومتنسوش إن الأنصار كانوا شكوا قبل كده في الموضوع ده بعد غزوة حنين لما رسول الله ﷺ كان بيوزع الغنائم وحصل إنهم زعلوا وبعدين رسول الله ﷺ وضح لهم الأمر زي ما شرحنا قبل كده،\nفإذا كان رسول الله ﷺ معملش كده ومرجعش لمكة فإيه إللي يمنع المهاجرين دلوقتي من إنهم يرجعوا إلى بلدهم بعد ما خلاص بقت آمنة بالنسبة لهم\nفإذا كان المهاجرين هيرجعوا لبلدهم خلاص، يبقى من المنطقي عشان المدينة تكون مستقرة إن يكون قائدها من أهل العاصمة بعد ما المهاجرين يمشوا\n☆ممكن حد يقول:\nخلاص في الحالة دي ممكن تنتقل عاصمة الدولة الإسلامية لمكة بدل ما تكون في المدينة\nمش من الحكمة أبداً أن تنقل العاصمة إلى هذا البلد المتقلّب؛\nلأن أهل مكة دخلوا الإسلام منذ أقل من ثلاثة أعوام فقط مضطرين، صرّح بذلك مَن صرّح، وأخفى ذلك من أخفى،\nفهم أيًّا كانوا لسه حديثوا عهد بجاهلية وشرك،\nوليس لهم فقه أهل المدينة ولا علمهم، ده حتى ممكن يرتدوا عن الإسلام لما يعرفوا إن رسول الله ﷺ مات خلاص\nفكده يبقى مش من الحكمة السياسية أبدا أن تنتقل الزعامة إلى مكة، \nفإذا كانت الخلافة ستبقى في المدينة والمدينة سيتركها المهاجرون فمن يحكم؟ \nالإجابة بسيطة وسهلة: لابد أن يكون من الأنصار\n◇ خامساً: \nالأنصار كانوا حاسين إن العرب ستستهدفهم بالقتال بعد وفاة رسول الله ﷺ، فالحقد يملأ قلوب العرب على الأنصار؛ \nلأنهم هم الذين ناصروا محمد ﷺ، \nوهم الذين قاتلوا هنا وهناك في بقاع مختلفة من الجزيرة،\nفلو مكنش لهم قوة الحُكم والسلطان فممكن يُبادوا إذا اجتمعت ضدهم قبائل العرب\nفعشان الأسباب دي وغيرها اعتقد الأنصار إنه من المنطقي أن يكون الخليفة من بينهم وليس من المهاجرين، \nوده مش تقليل من شأن المهاجرين في نظرهم أبداً، ولا إهمالاً لهم، ولكن لأنهم كانوا مفكرين إن ده حق لا ينازعهم فيه أحد\nفاحنا كل ده بنشرح الأمر من وجهة نظر الأنصار، بغض النظر هل وجهة النظر دي صحيحة ولّا لأ\n☆ممكن حد يسأل ويقول:\nطيب هو مش كان الأحسن إن الأنصار يخبروا المهاجرين باللي هم ناويين يعملوه والأسباب إللي عندهم،\nعشان محدش يشك فيهم أصلا \nأيوة فعلا، كان الأحسن إنهم يعملوا كده،\nولكن في احتمال إنهم ظنوا إن المهاجرين مش هيفكروا أصلا في الخلافة؛ لأنهم مفكرين إن ده حقهم الكامل فليه يقولوا أصلا،\nوممكن إنهم كانوا عايزين يقفلوا باب الفتنة ومنع الجدال بإنهم يحسموا الموضوع،\nأو ممكن لأنهم شافوا إن المهاجرين كانوا مشغولين بتغسيل وتكفين رسول الله ﷺ ومكنوش عايزين يشغلوهم بحاجة متخصهمش حاليا،\nيعني كل واحد له دوره المعين والمحدد في اللحظة دي يعمله وخلاص بدون ما يزعج التاني، وخصوصا إن الأمرين مهمين جدا فمحتاجين تركيز \nفخلاصة الكلام دلوقتي إن عدد كبير من قادة الأنصار من الأوس والخزرج اجتمعوا في سقيفة بني ساعدة،\nوفي الوقت ده تحديدا كان كبار المهاجرين زي أبو بكر وعمر وغيرهم حول رسول الله ﷺ مشغولين بيه وبقضية الغسل والتكفين ثم الدفن، \nهنغسله إزاي، وهنكفنه في إيه، وندفنه فين،\nهل في البقيع ولّا مع شهداء أُحد ولّا في مكة بلده ولّا في مكان خاص به؟\nوهم مشغولين كده جاء رجل لبيت رسول الله ﷺ ونادى من وراء الجداء وقال:\nاخرُجْ إليَّ يا ابنَ الخطَّابِ.\nفقال له عمر: إليك عنِّي فإنَّا مشاغيلُ.\nيعني روح دلوقتي احنا مش فاضيين،\nلكن الرجل أصرّ على عمر إنه يخرج له، فلما خرج عمر قال له الرجل : \n\"إنَّه قد حدَث أمرٌ لا بدَّ منك فيه، إنَّ الأنصارَ قد اجتمَعوا في سَقيفةِ بني ساعدةَ فأدرِكوهم قبْلَ أنْ يُحدِثوا أمرًا فيكونَ بينَكم وبينهم فيه حربٌ\"\nيعني بيقول له إن في حاجة حصلت ولازم تعرفها عشان تعرف تتصرف،\nالأنصار اجتمعوا في سقيفة بني ساعدة وشكلهم ناويين على \nحاجة، فالحقوهم قبل ما ياخدوا قرار وتحصل حرب بسبب القرار ده،\nوالرجل كلامه منطقي،\nماهو لو الأنصار أخذوا قرار البيعة واختاروا خليفة لا يرضى عنه المهاجرون فإما أن يبايعوا على ما لا يرضون، وإما أن يرفضوا البيعة وكده هتحصل أزمة،\nفهنا عمر رضي الله عنه نادى على أبي بكر وقال له:\nانطلِقْ بنا إلى إخوانِنا هؤلاء مِن الأنصارِ.\nيعني تعال نروح للأنصار ونشوف اجتمعوا ليه وناويين على إيه، فأسرع أبو بكر وعمر لسقيفة بني ساعدة،\nوهمّ ماشيين قابلوا رجلين صالحين من الأنصار القُدامى من إللي شهدوا بيعة العقبة الثانية وحضروا كل معارك رسول الله ﷺ،\nوهما: عُوَيم بن ساعدة ومَعِن بن عَدِي رضي الله عنهما، \nفلما شافوا إن أبا بكر وعمر رايحين للثقيفة نصحوهم بإنهم ميقربوش منها وإنهم كمهاجرين يصرفوا أمورهم بينهم وبين نفسهم وميتدخلوش في اجتماع الأنصار،\nواضح طبعا إنها كانوا خايفين تحصل فتنة بين المهاجرين والأنصار فكانوا عايزينهم يمشوا وميتقابلوش مع الأنصار،\nلكن أبو بكر وعمر أصروا على الذهاب إلى السقيفة،\nفي الطريق قابل أبو بكر وعمر أمين الأمة أبو عبيدة عامر بن الجراح، وهو من أعظم المهاجرين رضي الله عنهم أجمعين فأخذاه معهما إلى سقيفة بني ساعدة\nوصل الثلاثة لسقيفة بني ساعدة ودخلوها،\nإيه الحوار إللي حصل بينهم؟\nوإيه كان نتيجة الاجتماع ده؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \nمصادر جزء النهاردة في التعليقات"}, {"n": 263, "l": "الجزء 237 | ابو بكر وعمر وابو عبيده ف السقيفة", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وسبعة_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#أبو_بكر_وعمر_وأبو_عبيدة_في_السقيفة\nاتكلمنا المرة إللي فاتت عن اجتماع الأنصار في سقيفة بني ساعدة عشان يختاروا خليفة منهم،\nوقلنا إن اجتماعهم كان بدون وجود المهاجرين، وإن الخبر وصل لعمر بن الخطاب رضي الله عنه فأخذ أبا بكر وتوجهوا للسقيفة وهمّ ماشيين قابلوا أبو عبيدة بن الجراح فأخذوه معاهم وراحوا للسقيفة مع بعض،\nفي الوقت ده كان الأنصار اجتمعوا في الرأي على إن خليفة المسلمين يكون سعد بن عبادة رضي الله عنه،\nهنا دخل أبو بكر وعمر وأبو عبيدة سقيفة بني ساعدة\nلما دخلوا لقوا الأنصار مجتمعين على رجل قاعد متغطي بغطاء، فسأل عمر عنه قالوا إن ده سعد بن عبادة،\nفسأل ماله متغطي ليه كده، فقالوا له إنه عنده حمى ومريض.\n☆طيب سؤال، \nلماذا اختار الأنصار سعد بن عبادة بالذات\nسعد بن عبادة هو زعيم قبيلة الخزرج، وله فضائل إيمانية عالية،\nمنها إن رسول الله ﷺ كان جعله واحد من النُّقباء الاثنا عشر في بيعة العقبة الثانية،\nوكان من إللي شهد المشاهد كلها مع رسول الله ﷺ، وله مواقف مشهورة في الغزوات وخصوصا في غزوة الخندق لما رفض إعطاء غطفان ثمار المدينة واتكلمنا عن الموضوع بالتفصيل ساعتها ونزل رسول الله ﷺ على رأيه في كده،\nوكان رسول الله بيقدّره ويُكثر من زيارته، ودعا له رسول الله ﷺ وقال:\n\"اللهُمَّ اجعَلْ صلَواتِكَ ورَحمتِكَ علَى آلِ سعدِ بنِ عُبادَةَ \"\nوكان سعد بن عبادة رضي الله عنه كريم جدا، \nفكان لوحده بياخد ثمانين رجل من أهل الصُّفّة عشان يُطعمهم في بيته،\nيعني الرجل من الأنصار كان يأخذ رجل أو رجلين أو حتى خمسة رجال من أهل الصفة فيطعمهم على حسب إمكانيات كل واحد،\nلكن سعد رضي الله عنه بياخد بالثمانين رجل\n☆واحنا شرحنا معنى أهل الصُّفَّة في الجزء المائة وواحد وأربعين، ومعناه سريعا كده:\nالصُّفَّة أو الظُّلَّة مكان في آخر المسجد النبوي أمر به رسول الله ﷺ إنه يُظلل بجريد النخل، وأُطلق عليه اسم \"الصُّفَّة\" أو \"الظُّلَّة\nورسول الله ﷺ جهز المكان ده عشان يكون مأوى للغرباء أو العُزاب من المهاجرين والوافدين إللي ملهمش مأوى ومكان يسكنوا فيه، وبقى اسمهم أهل الصُّفة،\nوساعات أعدادهم تكون قليلة وساعات تكون كبيرة.\nفالشاهد من الكلام إن سعد رضي الله عنه كان سَخي وواسع العطاء،\nوكان برده كان وقّاف عند كتاب الله وعند كلام رسول الله ﷺ، يعني كان لما تأتيه آية أو حديث يتبعها ويسلم لها حتى وإن كان الأمر مخالف لما يريده رضي الله عنه \nفكل الصفات دي وغيرها جعلت الأنصار من الأوس والخزرج يجتمعوا على اختياره خليفة للمسلمين، لكن لسه لم يبايعوه،\nقبل ما يبايعوه كان جاء الثلاثة ودخلوا،\nوالأنصار مكنوش متوقعين أن يأتي أحد من المهاجرين،\nلكن دلوقتي مش بس جاء ناس من المهاجرين؛ ده إللي جاءوا ثلاثة من أصحاب الرأي والمشورة من الصحابة،\nوزير رسول الله ﷺ الأول أبو بكر والوزير الثاني عمر،\nوأبو عبيدة الأمين إللي رسول الله ﷺ كان كثيرا ما يستشيره فنقدر نقول إنه الوزير الثالث،\nفلا شك أنهم يمثّلون الآن رأي المهاجرين\nوكده ممكن تحصل مواجهة\nالأنصار عايزين سعد بن عبادة رضي الله عنه، والمهاجرون لسه مقلوش رأيهم،\nلكن ممكن يكون لهم رأي آخر، وهنا حصلت لحظة هدوء والكل مترقب الأحداث\nيا ترى المهاجرين هيقولوا إيه؟\nهل هيوافقوا على خلافة سعد بن عبادة الأنصاري أم سيرشحون خليفة غيره؟\nدخل الثلاثة وجلسوا، مفيش وقت بسيط إلا وقام خطيب الأنصار وبدأ يتكلم،\nاسم إللي تكلم ده غير معروف، لم يذكره المؤرخون، وممكن يكون الخطيب ده هو ثابت بن قيس رضي الله عنه؛ لأن هو إللي كان يُطلق عليه خطيب الأنصار، فالله أعلم\nالمهم الخطيب قام وتكلم، فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ:\n\" أَمَّا بَعْدُ ، فَنَحْنُ أَنْصَارُ اللَّهِ وَكَتِيبَةُ الإِسْلاَمِ ، وَأَنْتُمْ مَعْشَرَ المُهَاجِرِينَ رَهْطٌ...\"\nيعني بيقول إن الأنصار هم كتيبة الإسلام وأنصار الله بينما المهاجرون رهط، يعني عدد قليل.\nوفي رواية: رهط منا، يعني عدد قليل بالنسبة لنا، \nوكأنه توقع أن المهاجرين هيكونوا عايزين الخلافة، فسبّق بالكلام عشان يُبطل أي حجة للمهاجرين بأنهم أعداد قليلة بالنسبة للأنصار،\nوطبعا الأنصاري يقصد المهاجرين قبل فتح مكة الذين هاجروا إلى المدينة وإللي عايشين حاليا في المدينة، \nوإلا فلو اعتبر أعداد القرشيين في مكة مع إللي أسلموا بعد الفتح فهيكونوا أضعاف أضعاف الأنصار\nالمهم هو قال الكلام ده كتلميح إلى أن الخلافة يجب أن تكون في العدد الأكبر الذي نصر الإسلام في كل المشاهد والمواقع بنسبة دائماً ما تكون أكبر من المهاجرين.\n☆فالكلام ده كده فيه بوادر أزمة ومشكلة\nكلامه في البداية كان مجرد تلميح، لكنه بعدها قالها صريحة كده:\n\"وَقَدْ دَفَّتْ دَافَّةٌ مِنْ قَوْمِكُمْ، فَإِذَا هُمْ يُرِيدُونَ أَنْ يَخْتَزِلُونَا مِنْ أَصْلِنَا ، وَأَنْ يَحْضُنُونَا مِنَ الأَمْر\"\nيعني بيقول إنهم بعد ما خلاص استقروا على رجل يكون هو الخليفة جاءت مجموعة قليلة من المهاجرين《 إللي هم أبو بكر وعمر وأبو عبيدة 》عايزين يستثنونا من الخلافة في بلادنا،\nيعني الخلافة حق الأنصار وانتم جايين عشان تاخدوها مننا، وبعدين سكت الخطيب.\n☆الموقف ده كده ممكن ياخدنا لدعوى القبلية والجاهلية والفُرقة وده يقول احنا المهاجرين والتاني يقول احنا الأنصار وتحصل أزمة بين الطرفين زي ما حصل قبل كده وكان رسول الله ﷺ نهى عنها،\nفلازم هنا الحكمة الشديدة والحرص البالغ في معالجة الموقف والموضوع لسه في الأول\nعمر كان قاعد بيسمع كلام الخطيب، فكان بيجهز في نفسه كلام عشان يرد بيه على خطيب الأنصار، \nفلما سكت الخطيب لسه عمر هيقوم عشان يتكلم راح أبو بكر موقفه وقال له:\nعَلَى رِسْلِكَ\nيعني استنى استنى متقومش، أنا إللي هتكلم\nلأن أبو بكر رضي الله عنه عارف عمر وشدته، فخاف أحسن يقول كلام شديد يعقّد الموقف\nفعمر رضي الله عنه بيقول:\n\"فَكَرِهْتُ أَنْ أُغْضِبَهُ، فَتَكَلَّمَ أَبُو بَكْرٍ فَكَانَ هُوَ أَحْلَمَ مِنِّي وَأَوْقَرَ ، واللهِ مَا تَرَكَ مِنْ كَلِمَةٍ أَعْجَبَتْنِي فِي تَزْوِيرِي ، إِلَّا قَالَ فِي بَدِيهَتِهِ مِثْلَهَا أَوْ أَفْضَلَ مِنْهَا حَتَّى سَكَتَ\"\nيعني عمر بيقول إنه محبش يزعل أبا بكر فسمع كلامه وقعد وخلّاه هو إللي يتكلم،\nوكل الكلام إللي كان في نَفْس عمر وكان عايز يقوله أبو بكر رضي الله عنه قاله كله وأحسن منه كمان،\nوقال الكلام بهدوء ووقار ومن غير أي شدة، وكان رضي الله عنه إذا تكلم الصحابة رضي الله عنهم بينصتوا له\n☆أبو بكر رضي الله عنه قال إيه بقى \nنقدر نقول إن أبا بكر رضي الله عنه قسّم كلامه إلى ثلاثة أقسام أو ثلاث مراحل في غاية الحكمة:\n◇أولا: ذَكَر فضل الأنصار.\nقال عمر: \n\"فَلَمْ يَتْرُكْ شَيْئًا أُنْزِلَ فِي الْأَنْصَارِ وَلَا ذَكَرَهُ رَسُولُ الله مِنْ شَأْنِهِمْ إِلَّا ذَكَرَهُ\"\nيعني ذكر كل المديح الذي جاء في الأنصار سواء في القرآن أو في السنة، زي مثلا قول رسول الله ﷺ:\n\"الأنْصارُ لا يُحِبُّهُمْ إلَّا مُؤْمِنٌ، ولا يُبْغِضُهُمْ إلَّا مُنافِقٌ، فمَن أحَبَّهُمْ أحَبَّهُ اللَّهُ، ومَن أبْغَضَهُمْ أبْغَضَهُ اللَّهُ\"\nوقوله:\n\"لولا الهجرة لكنتُ امرأً من الأنصار\"\nوذكّرهم بقول رسول الله ﷺ:\n\"لو سلك الناس وادياً وسلك الأنصار وادياً لسلكتُ وادي الأنصار\"\nوغيرها وغيرها من فضائلهم رضي الله عنهم، فبعد ما ذَكَر فضائلهم كلها قال:\n\"وما ذكرتُ فيكم من خيرٍ فأنتم أهله، وإنا والله يا معشر الأنصار! ما ننكر فضلكم ولا بلاءكم في الإسلام ولا حقكم الواجب علينا\"\nيعني كل الحاجات إللي أنا قلتها انتم فعلا تستحقوها ودي حقيقة مش محتاجة مجاملة،\nواحنا لا ننكر فضلكم ولا تضحياتكم إللي انتم قدمتوها لخدمة الإسلام ولا نُنكر حقكم الواجب علينا\n☆المقدمة إللي قالها أبو بكر دي كانت سبب في هدوء نفوس الأنصار وبقى في جو من السكينة داخل السقيفة،\nوبكده يكون أبو بكر احتوى الأنصار وبقى في فرصة إنهم يتقبلوا الكلام إللي هيقوله كله بدون شد أعصاب وجدال\nعارفين زي إيه\nزي كده لما يكون في بين اتنين مشكلة وواحد يبدأ يتكلم 《بحق وبدون كذب أو نفاق》 عن فضائل الطرف التاني،\nالكلام ده بيشرح الصدر وبيخفف حِدة المشكلة والأمور تبدأ تاخد منحنى الهدوء وبالتالي المشكلة تتحل\nفدي كده كانت أول مرحلة أو أول خطوة في كلام الصديق رضي الله عنه\n◇ثانيا: اتكلم عن الحق الذي لابد منه\nقال أبو بكر:\n\"ولن تعرِفَ العربُ هذا الأمرَ إلَّا لهذا الحيِّ مِن قريشٍ هم أوسطُ العربِ نسبًا ودارًا\"\nيعني هو بيوضح للأنصار بهدوء إن الحكمة تقتضي أن تكون الخلافة في قريش؛ لأن العرب لن تسمع ولن تطيع إلا لقريش، فمنهم النبي ﷺ وهم أوسط العرب نسباً وأكثر العرب قرباً لقلوب العرب؛ \nوده لمكانة مكة الدينية القديمة في قلوب الناس،\nفإذا كان الخليفة من قريش اجتمع العرب عليه مهما اختلفت قبائلهم، وإن كان من غيرهم لم يقبلوا به مهما كان هذا الخليفة رجلاً صالحاً عادلاً تقياً\nيعني القضية مش تقليل أو تهميش للأنصار رضي الله عنهم، فهم فعلاً أهل الفضل وأنصار الإسلام،\nولا القضية حكم المدينة فقط عشان نختار حاكم من أهلها عليها،\nلكن يجب على الأنصار إنهم يفتحوا عينهم ويشوفوا الصورة كاملة عشان يفهموا إن الخليفة المُنتخَب ده يجب أن يسمع له ويطيعه كل العرب دلوقتي، وهيسمع له كل الأرض بعدين\nوحتى يعني لو الأنصار اختاروا رجل هو أتقى وأفضل من أي رجل من المهاجرين أليس من الحكمة أن يتولى الأصلح الذي يجتمع عليه الناس جميعاً\nيعني مثلا واحد كويس وتقي وفيه كل المميزات وأفضل الناس، لكن مش كل الناس مجتمعين عليه،\nفي حين إن في واحد تاني أقل من الأول وينفع للخلافة والناس كلها مجتمعين عليه، يبقى نختار مين\nطبعا من باب فقه الواقع هنختار الأصلح وإللي الناس هتكون مجتمعة عليه،\nفالموضوع مش من باب القبلِيّة والعنصرية، ولكنه من باب فقه الواقع، فالواقع يُملي شروطه، والخليفة يجب أن يكون من قريش وبالذات في ذلك الزمن، \nوغير كده، هو مفيش حد من المهاجرين يساوي سعد بن عبادة في الفضل أو حتى يفوقه ويفوق كل الصحابة؟\nأكيد طائفة المهاجرين مليانة بأصحاب الفضل والرأي والحكمة والتقوى\nيبقى الرأي إللي قدمه أبو بكر رضي الله عنه إن الخليفة يكون من قريش هو رأي منطقي ومعقول وله أبعاده الواقعية\nهندخل بقى في المرحلة الثالثة من كلام أبو بكر وهي:\n◇عرض المرشحين للخلافة.\nأخذ أبو بكر بيد عمر وبيد أبي عبيدة وقال للأنصار:\n\"وقد رضيتُ لكم أحدَ هذينِ الرَّجلينِ فبايِعوا أيَّهما شِئْتُم\"\nيعني الاتنين دول شخصين مناسبين جدا وأنا موافق عليهم فاختاروا واحد منهم،\nوهنا كلام أبو بكر ده دليل عملي واضح أمام الأنصار إنه لم يعرض فكرة إن الخليفة يكون من قريش عشان هو طمعان في الخلافة، بالعكس،\nده مع إنه هو أفضل المهاجرين وأفضل الناس على الإطلاق بعد رسول الله ﷺ إلا إنه اختار حد تاني خالص غير نفسه لأنه زاهد فيها ومش عايزها،\nوهو مش بيقول الكلام ده من باب السياسة ولا الورع الكاذب زي ما بنشوف\nمن خلال حياة الصديق رضي الله عنه يظهر لنا إنه كان صادق فعلا في كلامه وإن عمره ما كان عايز الإمارة ولا حتى عنده رغبة فيها\n☆حتى يا جماعة لما أبو بكر هيمسك الخلافة بعدين خلال فترة حكمه لم يظهر عليه شيء يُشير إلى إنه كان عايز الإمارة، بالعكس ده كان عابد زاهد مجاهد، وكان كثير التفكير، كثير السهر، كثير العمل، ولم يستمتع بدنيا ولا بسلطة ولا بقيادة\nيبقى دلوقتي أبو بكر رشح للأنصار عمر وأبو عبيدة، طول ما كان أبو بكر بيتكلم كان عمر مبسوط بالكلام إللي بيقوله وكان مؤيد لكل كلام أبو بكر،\nلحد ما أبو بكر أخذ يد عمر وقال إنه بيرشحه هنا عمر بيقول عن نفسه:\n\"فلم أكرَهْ شيئًا مِن مقالتِه غيرَها، واللهِ لَأنْ أُقدَّمَ فتُضرَبَ عنقي في أمرٍ لا يُقرِّبُني ذلك إلى إثمٍ أحَبَّ إليَّ مِن أنْ أُؤمَّرَ على قومٍ فيهم أبو بكرٍ\"\nيعني دي الحاجة الوحيدة إللي كرهها عمر من كلام أبي بكر،\nفهو عنده القتل في غير معصية أحب إليه من إنه يكون أمير على قوم فيهم أبو بكر رضي الله عنه.\nكده بقى عندنا رأيين،\nرأي بيؤيد مرشح من الأنصار ويقف وراءه معظم رؤساء الأنصار في المدينة،\nورأي تاني بيؤيد مرشح من قريش ويقف وراءه ثلاثة فقط من المهاجرين وكل واحد له حجته ومنطقه، \nوده مش خلاف بسيط عابر، ده خلاف على مُلك ورئاسة وسلطان، فيا ترى بقى هيطلعوا من الخلاف ده إزاي؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \nمصادر جزء النهاردة في التعليقات"}, {"n": 264, "l": "الجزء 238 | بين المهاجرين والانصار في السقيفة", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثمانية_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#بين_المهاجرين_والأنصار_في_السقيفة\nاتكلمنا المرة إللي فاتت عن أبي بكر الصديق رضي الله عنه لما تكلم أمام الأنصار وقدّم لهم عمر وأبا عبيدة عشان يختاروا واحد منهم يكون خليفة للمسلمين،\nوقلنا إن كده بقى عندنا رأيين:\nرأي بيؤيّد مُرشح من الأنصار ويقف وراءه معظم رؤوس الأنصار في المدينة،\nورأي تاني بيؤيد مرشح من قريش ويقف وراءه ثلاثة فقط من المهاجرين وكل واحد له حجته ومنطقه، \nهنا قام واحد من الأنصار هو الحُبَاب بن المنذر وقال:\n\"مِنَّا أمِيرٌ، ومِنكُم أمِيرٌ، يا مَعْشَرَ قُرَيْشٍ\"\nيعني بيقترح اختيار أميرين، أمير من الأنصار على الأنصار وأمير من المهاجرين على المهاجرين أو يختار أميرين تكون لهما القيادة على دولة الإسلام هم الاتنين مع بعض،\nهو شاف إن ده حل يرضي جميع الأطراف\nوأكمل كلامه وقال:\nفإنا والله! ما نَنْفس عليكم هذا الأمر، ولكنا نخاف أن يَلِيَها أقوام قتلنا آباءهم\"\nيعني احنا مفيش في نفوسنا شيء عليكم، لكن هم خايفين؛ لأن الأنصار قتلوا عدد كبير من أهل مكة من القرشيين في الغزوات،\nوالموضوع ده سيترك ثأر في قلوب قريش، فإذا تولى القرشيون الخلافة ممكن ينتقموا من الأنصار.\nوهنا هنلاحظ ثلاثة أمور في كلام الحُباب بن المنذر رضي الله عنه:\n◇أولا:\nإن في تنازل سريع من الأنصار عن موقفهم من اختيار الخليفة منهم، يعني همّ لسه من شوية كانوا مجتمعين على سعد بن عبادة كخليفة لكل الدولة الإسلامية، \nلكن بعد كلام أبي بكر تنازلوا عن نصف الخلافة، فدي كده محاولة صادقة منهم لتقريب وجهات النظر والالتقاء في منتصف الطريق\n◇ثانيا:\n إللي خلّى الحُباب يقول الكلام ليس الحقد على المهاجرين، ولكن خوفهم من نظام جديد ممكن يكون فيه خطورة على حياتهم جميعاً\n☆وهو إيه النظام الجديد ده\nشوفوا،\nالعرب بصفة عامة لم تكن تُقر وترضى بالسيادة لأحد على قوم إلا لمن يكون منهم، \nيعني مهما صَغُرت القبيلة فإن رئيسها يكون منها،\nزي حالنا دلوقتي كده،\nهو في دولة مثلا حتى ولو كانت مسلمة ترضى إن يكون رئيسها من دولة تانية؟ لا طبعا مفيش\nشوفتم إزاي إننا رجعنا لأيام الجاهلية\nالمهم يعني كان طبيعي إن الأنصار يستغربوا كعامة العرب إن إزاي يكون عليهم أمير من غيرهم،\nوهم كانوا تقبلوا برسول الله ﷺ كحاكم عليهم من بلد تانية؛ لأنه كان نبي زي ما قلنا قبل كده،\nوالقبلية كانت من الموانع الرئيسية لكثير من الناس في دخول الإسلام، فجاء الإسلام وألغى القبلية،\nلكن دي قواعد إدارة البلاد لمدة سنوات كثيرة جدا،\nولم يبتعدوا عن هذه القواعد إلا منذ سنوات معدودات، حوالي احدى عشر سنة تقريبا من ساعة الهجرة،\nفكلام الحُباب إن يكون في أمير منهم وأمير من المهاجرين كان طبيعي وخصوصا إن ده أول حاكم هيحكم بعد رسول الله ﷺ\n◇ثالثا:\nبصرف النظر عن الظروف إللي خلت الحُباب رضي الله عنه يقترح الاقتراح ده؛ هل من  الحكمة أن يتولى الخلافة رجلان\nيعني عندنا مَثَل بيقول: المَركب إللي فيها ريِّسِين تغرق،\nفإزاي بقى يكون في بلد يدير شؤونها خليفتين؟\nمستحيل طبعا، \nده غير كده كمان الموضوع مَنهِي عنه في الشرع، وفي منتهى الوضوح وفي منتهى الصرامة\nقال رسول الله ﷺ:\n\"مَن بايع إمامًا فأعطاه صفقةَ يدِه ، وثمرةَ قلبِه ، فلْيُطِعْه ما استطاع ، فإن جاء أحدٌ يُنازِعُه فاضربوا رقبةَ الآخرِ\"\nيعني إذا الناس بايعوا إمام ورضوا به، فليطيعوه مادامت طاعته في غير معصية الله،\nفإذا جاء واحد تاني يُنازعه في الحكم وعايز ياخده منه، فالمطلوب من المسلمين إنهم يدفعوا الشخص التاني ده لأنه خارج على الإمام،\nفإنْ لم يندفِعْ إلَّا بحرْبٍ وقتالٍ، فقاتِلُوه، فإنْ دعَتِ المُقاتَلةُ إلى قتْلِه، جاز قتْلُه، ولا ضمانَ فيه؛ لأنَّه ظالمٌ مُعتدٍ في قتالِه\nطبعا يا جماعة الحُباب بن المنذر رضي الله عنه إما إنه لم يصله الحكم ولا يعرفه،\nأو إنه كان عايز الأنصار ينسحبوا من الخلافة ولكن بأسلوب متدرج؛ عشان ميكونش في إحراج لكبيرهم سعد بن عبادة رضي الله عنه،\nو اقتراحه ده مكنش هيعدي على الصحابة يعني، فلو كان في ناس مش عارفين ففي غيرهم عارفين الحكم\n☆وأنا عايز أوضح لكم نقطة مهمة\nمش كل الصحابة كان عندهم كل العلم عن رسول الله ﷺ والقرآن،\nالعلم إللي رسول الله ﷺ قاله متفرق ومتوزّع بين الصحابة، يعني ممكن واحد بس من الصحابة يكون سمع حديث معين من رسول الله ﷺ محدش سمعه غيره،\nوممكن يكون مجموعة سمعوا حديث لرسول الله ﷺ وواحد تاني مسمعش الحديث،\nفالعلم متفرق بين الصحابة وهم بينقلوه لغيرهم، \nعشان كده متستغربوش لما تعرفوا إن واحد من الصحابة مثلا مكنش يعرف حكم معين أو ميعرفش حديث معين،\nاحنا يا جماعة لسه في البداية خالص، متخيلين إن القرآن نفسه مكنش لسه اتجمع وكان متفرق بين الصحابة،\nيعني احنا دلوقتي بسهولة ممكن نعمل بحث على أي حديث ونعرف مين الرواي وهل الحديث ده صحيح أو لأ،\nلكن في عهد الصحابة مكنش الكلام ده موجود خالص، \nفأنا عايزاكم وانتم بتقرأوا عن الصحابة بصفة عامة وعن الموقف إللي بنتكلم عنه دلوقتي بصفة خاصة تبقوا متخيلين عصر الصحابة ده كان عامل إزاي،\nوالعلم عندهم كان متفرق بينهم إزاي\nالمهم،\nبعد ما الحباب قال رأيه كَثُرَ \"اللَّغَط\" يعني بقى في جَلَبة ودوشة والكل بقى يتكلم وارتفعت الأصوات،\nفهنا قال عمر:\nإنه لا يصلح سيفان في غِمْدٍ واحد\nهو احنا ينفع نضع سيفين في نفس الجراب بتاع السيف الواحد؟ لأ طبعا، فعمر هنا يقصد إنه لا يصلح خليفتان في البلد\nفقام خطيب الأنصار إللي كان اتكلم من شوية وقال:\n\"إِنَّ رَسُولَ اللَّهِ ﷺ كَانَ إِذَا اسْتَعْمَلَ رَجُلًا مِنْكُمْ قَرَنَهُ بِرَجُلٍ مِنَّا فَتَبَايَعُوا عَلَى ذَلِكَ\"\nيعني رسول الله ﷺ كان دايما بيخلي المهاجرين والأنصار مع بعض في كل شيء، فهو بيقول خلاص خلونا نعمل زي رسول الله ﷺ ويبقى واحد مننا وواحد منكم،\nيعني هو بيؤيد رأي الحباب رضي الله عنه،\nلكن هنلاحظ إن كلامه فيه تنازل أكبر،\nيعني هو بيقبل بخليفة من المهاجرين ومعاه مساعد من الأنصار،\nلكن برده الظاهر من كلامه أنه لا يقصد نائباً للخليفة، لأ هو يقصد خليفة ولكن في درجة لاحقة للخليفة الأول،\nوطبعا زي ما قلنا الكلام غير منطقي خالص\nفقال واحد من الأنصار:\n\"أَوَّلًا نَخْتَارُ رَجُلًا مِنَ الْمُهَاجِرِينَ وَإِذَا مَاتَ اخْتَرْنَا رَجُلًا مِنَ الْأَنْصَارِ،\nفَإِذَا مَاتَ اخْتَرْنَا رَجُلًا مِنَ الْمُهَاجِرِينَ كَذَلِكَ أَبَدًا،\nفَيَكُونُ أَجْدَرَ أَنْ يُشْفِقَ الْقُرَشِيُّ إِذَا زَاغَ أَنْ يَنْقَضَّ عَلَيْهِ الْأَنْصَارِيُّ وَكَذَلِكَ الْأَنْصَارِيُّ\"\nيعني خلاص احنا في الأول هنختار خليفة من المهاجرين، وبعدين لما يموت نختار واحد من الأنصار، ويستمر الوضع كده للأبد، واحد من هنا وواحد من هنا\nوبكده مش هيبقى في أي انحراف في السُّلطة، يعني كده المهاجري هيبقى عارف إن الخلافة هتروح لواحد غيره من قبيلة تانية فمش هيقدر إنه يستغل سلطته كخليفة من المهاجرين لمصلحته الشخصية مثلا\nوالرأي ده وإن كان ظاهره إنه هيحل الموقف الآن باختيار خليفة من المهاجرين إلا أنه سيؤجل الفتنة عدة سنوات أو شهور،\nلكن أكيد هتحصل فتنة؛ لأن الشيطان ممكن يدخل \nبين الفريقين ويعمل بينهم فتنة في تبادل السلطة، \nوالأهم من ده إن العرب في المستقبل بعد موت الخليفة الأول لن ترضَ بالخليفة الأنصاري الجديد\nفكده الرأي ده كمان غير مقبول\nفهنا عمر رضي الله عنه قال في قوة وحدة وفي منتهى الشدة: لا والله! لا يخالفنا أحد إلا قتلناه\nعمر رضي الله عنه كان شديد في الحق وحريص على الوضوح، وبعيد كل البعد عن تمييع الأمور،\nفهو هنا عايز يوضح الأمور على حقيقتها من البداية، فإن كانت الخلافة فعلاً من حق قريش زي ما وضح أبو بكر في بداية كلامه فأي حد هينازعهم فيها لابد أن يُقتل شرعاً\nفإذا كانت العرب جميعاً ستُبايع القرشيين ولن تبايع الأنصار فالاجتماع هنا على القرشيين واجب، \nوهنا هتكون مطالبة الأنصار بالإمارة مخالفة شرعية؛ لأنها ستقود إلى الفرقة وإلى الفتنة، والفتنة أشد من القتل،\nعشان كده رسول الله ﷺ شَرع قتل الخليفة الآخر إذا بُويع للأول واجتمع الناس عليه وكان مُقيماً لشرع الله غير مبدل ولا مُحرّف،\nفعمر رضي الله عنه مواقفه دائما كانت فاصلة،\nبيحب يوضّح الأمور على حقيقتها وإن كان موقفه يغضب بعض الناس أو يظنون فيه الظنون\nطبعا الحِدة إللي ظهرت في كلام عمر رضي الله عنه \nأثارت نفوس بعض الأنصار،\nلأن النفس العربية بصفة عامة لا تقبل التهديد وبالذات لو كانت هذه النفس نفس فارس،\nفقام فارس الأنصار الحُباب بن المنذر رضي الله عنه وأعاد وكرر: منا أمير ومنكم أمير، وإِنْ شِئْتُمْ كَرَّرْنَاهَا خُدْعَةً،\nيعني أعدنا الحرب من جديد،\nوطبعا الكلمة دي نقدر نقول إنها فلتت من الحباب رضي الله عنه بسبب الموقف كله  وإن كان فيه قلق وتوتر،\nوده وارد يا جماعة عادي، يعني هُم على عُلو شأنهم ومكانتهم فهم في الأول وفي الآخر بشر وقاعدين بيجتهدوا عشان يخرجوا بأفضل حل للموضوع وخصوصا إن ده حدث أول مرة يحصل، فتخيلوا الضغط إللي كانوا فيه،\nوعشان تعرفوا إن الموضوع مكنش شخصي وحرص على الإمارة هنلاحظ إن:\n◇أولا:\n مع الحوار والجدل ده كله لم نسمع إن سعد بن عبادة رضي الله عنه اتكلم ولا مرة، يعني من ساعة ما دخل المهاجرون في أول اللقاء لم يتكلم ولا مرة، \nولم يطلب لنفسه شيء ولم يبرر ولم يقل: خلاص يا جماعة قومي اتفقوا علي وده إللي عندنا وانتهى الموضوع\n◇ثانيا:\n الأنصار مع كل هذا الحوار الطويل لم يذكروا ولو مرة واحدة مناً على المهاجرين ولا تَفضّلاً عليهم، يعني محدش فيهم قال:\nانتم جئتمونا مطردوين فآويناكم، فقراء فأغنيناكم، محتاجين فأعطيناكم و...و....\nمع إن كل ده واقع وصحيح، لكن أدب وخُلق الأنصار أغلق كل أبواب الشيطان لزرع الفتنة بينهم\n◇ثالثا:\nالمهاجرين لما طلبوا الإمارة فيهم لم يقولوا ولو مرة واحدة: إنهم أفضل من الأنصار، أو إن كفاءتهم القيادية أو الإدارية أو الأخلاقية أو الروحية أكبر من كفاءة الأنصار، أبداً\nكل إللي عايزين يثبتوه هو صدق الواقع، والواقع سواء كان حلو أو مر يقضي بأن العرب لن تطيع إلا لقريش لأنهم أهل البيت الحرام وخُدامه وسدنته، \nفالعرب ستطيع قريش الآن، وبعد عشر سنين ستطيع قريش، وبعد مائة سنة ستطيع قريش، وما دام الواقع لم يُحل حراماً أو يحرم حلالاً فلابد من مراعاته\nوزي ما قلنا قبل كده، إن المسلمين يجتمعوا على رجل مرجوح أو أقل صلاحاً أحسن من إنهم يفترقوا على رجل راجح أو أكثر صلاحاً\nفخُلاصة الكلام إنهم كانوا بيجتهدوا في أمر جديد أول مرة يحصل أمامهم، فكان الاختلاف طبيعي جدا، والعبرة بالنهاية والنتيجة وهي اجتماع القلوب مهما اختلفت الآراء\nالمهم لما الحُباب رضي الله عنه قال الكلمة إللي قالها دي الأصوات عليت والموقف بقى متأزم أكثر،\nفهنا أبو عبيدة بن الجراح رضي الله عنه قال:\n\"يا معشر الأنصار! إنكم أول من نَصَر وآزَر فلا تكونوا أول من بَدّل وغيَّر\"\nهو قال الكلمة دي وساد الصمت في المكان،\nالكلمة زلزلت قلوب الأنصار وهزت مشاعرهم،\nالأنصار الذين آووا ونصروا، وإللي كانوا قالوا قبل كده:\nيا رسول الله! اقسم بيننا وبين إخواننا النخيل، \nوإللي ربنا قال فيهم:\n\"يُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ\"\nالأنصار إللي رضيوا إن ميكنش لهم أي جزاء على بذلهم في الدنيا ورضوا بالجنة،\nالأنصار إللي قالوا:\n\"بايَعَنا علَى السَّمْعِ والطَّاعَةِ، في مَنْشَطِنا ومَكْرَهِنا، وعُسْرِنا ويُسْرِنا وأَثَرَةً عَلَيْنا، وأَنْ لا نُنازِعَ الأمْرَ أهْلَهُ، إلَّا أنْ تَرَوْا كُفْرًا بَواحًا، عِنْدَكُمْ مِنَ اللَّهِ فيه بُرْهانٌ\"\nكلمات أبو عبيدة خلتهم يفتكروا البيعة الخالدة، والهجرة، والنُّصرَة،\nوتذكروا الجهاد والشهادة، وتذكروا إخوانهم إللي قدموا أرواحهم وسبقوهم وما بدلوا وما غيروا،\n تذكروا سعد بن معاذ ، وتذكروا أسعد بن زرارة ، وتذكروا سعد بن الربيع ، وتذكروا أنصاراً عاشوا أنصاراً وماتوا أنصاراً، \nوتذكروا رسول الله ﷺ الحبيب الذي لم يفارقوه إلا من وقت بسيط ولسه نائم على سريره لم يُدفن، \nيا ترى الأنصار عملوا إيه بعد ما سمعوا كلام أبو عبيدة رضي الله عنه؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n♡ملحوظة:\nفي الغالب باقي لنا حلقتين ونخلص السيرة إن شاء الله \nمصادر جزء النهاردة في التعليقات"}, {"n": 265, "l": "الجزء 239 | الأئمه من قريش", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وتسعة_وثلاثين\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#الأئمة_من_قريش\nوقفنا المرة إللي فاتت عند مقولة أبو عبيدة بن الجراح للأنصار:\n\"يا معشر الأنصار! إنكم أول من نَصَر وآزَر فلا تكونوا أول من بَدّل وغيَّر\"\nفهنا بشير بن سعد الأنصاري الخزرجي إللي كان حضر بيعة العقبة الثانية، وهو أبو النعمان بن بشير أول مولود يُولد للأنصار في المدينة بعد الهجرة؛ قام فقال:\n\"يا معشر الأنصار!\nإنا والله لئِن كنا أولِي فضيلة في جهاد المشركين، وسابقة في هذا الدين؛ ما أردنا به إلا رضاء ربنا، وطاعة نبينا، والكَدْح لأنفسنا، \nفما ينبغي أن نستطيل بذلك، ولا نبتغي به من الدنيا عرضًا، فإن الله وليّ النعمة، ووليّ المنة علينا بذلك، \nألا إن محمدًا ﷺ من قريش، وقومُه أحقُّ به وأوْلَى، ولا يراني الله أُنازعهم في هذا الأمر أبدًا، فاتقوا الله، ولا تخالفوهم ولا تنازعوهم\"\nيعني بيقول للأنصار إنهم وإن كانوا أصحاب الفضل في جهاد المشركين بكثرة عددهم زي ما خطيب الأنصار قال من شوية،\nلكن بيفكرهم إنهم معملوش كده إلا لأنهم كانوا عايزين رضا الله وطاعة رسوله، وإنهم بيعمَلوا لأنفسهم عشان ربنا ينجيهم في الآخرة ويدخلهم الجنة،\nفعلى الأساس ده بيقولهم إن مينفعش بقى إننا نستغل الفضل ده عشان ناخد به مصلحة في الدنيا؛ لأن الموضوع كله فضل من الله وهو إللي هدانا لهذا فله الفضل والمنة،\nومحمد ﷺ من قريش وقومه أحق بخلافته وأوْلى،\nوبعدين وضع من نفسه قدوة وقال لهم إنه معندوش استعداد إن ربنا يراه وهو يُنازع قوم رسول الله ﷺ في الخلافة،\nوذكّرهم بالله وقال لهم لا يخالفوهم ويسمعوا كلامهم،\nوكده نلاحظ تغير خط الحوار في السقيفة، وكده بدأت نفوس الجميع تهدأ، \nوهنا قام سيد الأوس أُسَيْد بن حُضَيْر ودعا الأنصار إنهم يتركوا الأمر ويبايعوا المهاجرين وقال إنه خايف إن يحصل خلاف في المستقبل بين الأوس والخزرج إذا أحد الفريقين تولّى الخلافة، عشان كده هو بيُؤيّد المهاجرين\nفلما رأى أبو بكر رضي الله عنه إن النفوس بدأت تطيب باختيار الخليفة من المهاجرين أراد إنه يضيف حجة تقوّي   من هذا الاختيار،\nفقال الصديق رضي الله عنه:\n\"إن الله سمّانا الصادقين وسمّاكم المفلحين....\"\nأبو بكر رضي الله عنه بيُشير إلى قول الله عز وجل في سورة الحشر:\n\" لِلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِنْ دِيارِهِمْ وَأَمْوَالِهِمْ يَبْتَغُونَ فَضْلًا مِنَ اللَّهِ وَرِضْوَانًا وَيَنْصُرُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ هُمُ 《الصَّادِقُونَ》\"\nفده كده وصف المهاجرين، أما وصف الأنصار فجاء في الآية إللي بعدها، قال الله تعالى:\n\" وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالإِيمَانَ مِنْ قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِمَّا أُوتُوا وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُوْلَئِكَ هُمُ《الْمُفْلِحُونَ》\"\nفكلامه رضي الله عنه بيدل على ذكاءه وسعة اطلاعه على القرآن،\nوبعدين أبو بكر رضي الله عنه قال للأنصار:\nوقد أمركم الله أن تكونوا معنا حيثما كُنا، فقال في سورة التوبة:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ\"\nيعني هو استنبط حكم إن الخلافة تكون من المهاجرين من خلال الآية، \nومش بس كده، ده قال لهم حديث رسول الله ﷺ إللي بيقول:\n\"فمَن ولِيَ مِنكُم شيئًا يَضُرُّ فيه قَوْمًا ويَنْفَعُ فيه آخَرِينَ، فَلْيَقْبَلْ مِن مُحْسِنِهِمْ ويَتَجَاوَزْ عن مُسِيئِهِمْ\"\nاحنا شرحنا الحديث كامل في الجزء المائة واثنان وثلاثين، \nفرسول الله ﷺ هنا كان بيوصي بالأنصار، وكلامه فيه إشارة واضحة إن الخليفة ليس من الأنصار؛\nيعني إزاي هيوصي الخليفة عليهم إذا كان هو منهم أصلا\nوبكده هدأت النفوس أكثر وأكثر، وازداد توحد المسلمين في رأي واحد\nكل الأحداث إللي بتحصل دي وسعد بن عبادة رضي الله عنه كان ساكت ومتكلمش خالص،\nوموقفه يُعتبر موقف محرج\nيعني من ساعة أو ساعتين كان مُرشح للخلافة وكان تقريبا شبه مؤكد إنه خلاص هيبقى فعلا الخليفة، وفجأة كده الوضع يتغير تماما، \nولعله أصلا كان في حيرة من كل إللي بيحصل، والأفكار تزاحمت في رأسه بجانب إرهاقه بسبب مرضه،\nوأكيد دي حاجة مش هتعدي على أبي بكر رضي الله عنه، هو كان مراقب للموقف كله وبيتصرف بحكمة عشان يخرجوا من الموضوع بأفضل نتيجة بدون أي مشاكل،\nومن خلال الموقف كان واضح إن الأنصار رضي الله عنهم خلاص اقتنعوا عقلياً وقلبياً بأن المصلحة العليا للأمة تستلزم أن يكون الخليفة من المهاجرين وبالذات من قريش\nفي اللحظة دي بقى أبو بكر رضي الله عنه أظهر بالدليل الدّامغ والحجة الظاهرة البيّنة التي لم تترك أي شك في قلب أحد، سواء من المهاجرين أو الأنصار\n☆إيه هو الدليل ده بقى\nقال أبو بكر رضي الله عنه وهو يوجه الكلام لسعد بن عبادة نفسه:\nلقد علمت يا سعد! أن رسول الله ﷺ قال وأنت قاعد:\n\"ٌقريش وُلاةُ هذا الأمر فَبَرُّ الناس تبعٌ لبَرِّهم، وفاجرهم تَبع لفاجرهم\"\nيعني رسول الله ﷺ بيقول إن الخلافة في قريش؛ لأن الناس كلها بيتبعوهم،\nالإنسان البار الكويس كان بيتع رسول الله ﷺ إللي هو من قريش، \nوالفاجر كان يتبع الفاجر والكافر من قريش، يعني باختصار  إن قريش هي زعيمة العالم العربي والكل ماشي وراها بالسوء أو بالخير \nفدلوقتي بقى في كلام لرسول الله ﷺ قاله في وجود سعد بن عبادة وفي وجود أبي بكر، وهو هنا بيذكر سعد بالحديث،\nوواضح إن سعد بن عبادة رضي الله عنه كان نِسي الحديث ده،\nإما بقى بسبب إنه سمعه من رسول الله ﷺ من فترة طويلة أو بسبب الحزن على رسول الله ﷺ أو بسبب إنه مريض، أو غيرها من الأسباب\nالمهم إن لما سمع سعد بن عبادة رضي الله عنه كلام أبي بكر رد عليه وقال له:\n\"صَدَقت. أنتم الأمراء ونحن الوزراء\"\nيعني برغم كل الحوارات والجدال إللي حصل في السقيفة؛ الموضوع كله خلص في كلمتين\nوسعد رضي الله عنه متكلمش من ساعة ما جاء المهاجرين الثلاثة للسقيفة غير الكلمتين دول،\nوبكده يبقى هو حَسَم الموضوع تماما بإن الخلافة لقريش وليس للأنصار فيها أي حق؛ لأن الموضوع هنا اتحول لتشريع مش مجرد شورى واجتهاد \nيعني الشورى بتكون في حاجة معندناش فيها حكم ثابت، فبيجتمع أهل الرأي عشان يتناقشوا ويقدروا يطلعوا أفضل الآراء وإللي فيها المصلحة،\nلكن مينفعش مثلا يتشاوروا يبيعوا الخمر أو لأ؛ لأن ده له حكم ثابت في الإسلام،\nفبعد الحديث إللي قاله أبو بكر وشهد له سعد بن عبادة بقى لا يجوز اختيار خليفة إلا من قريش؛\nلأن الموضوع خرج من أيديهم وبقى حُكمه إلى الله عز وجل وإلى رسوله ﷺ، فلا يجوز مخالفته،\n قال الله تعالى: \n\"وَمَا كَانَ لِمُؤْمِنٍ وَلا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ فَقَدْ ضَلَّ ضَلالًا مُبِينًا\"\nمش مجرد طاعة بس، لأ، ده لازم كمان تكون النفوس راضية بحكم الله ده، مش يقبل حكم ربنا على مضص ويقول أمري لله أعمل إيه يعني، ويطبق أمر ربنا وهو كاره ومضطر\n \nربنا بيقول:\n\"فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا\"\n☆ممكن هنا حد يقول زيي كده لما سمعت القصة دي أول مرة:\nطب ما كان يقول الحديث من الأول\nلو كان قاله من بداية القعدة من أول ما دخلوا كان زماننا قفلنا كل أبواب الجدل من البداية وخِلصنا \nلكن سبحان الله الموضوع طلع له حكمة، وكان من توفيق الله لأبي بكر رضي الله عنه إنه ميقولش الحديث ده من البداية، ليه بقى\nتخيلوا إيه إللي كان ممكن يحصل لو كان أبو بكر قال الحديث من غير ما يمهّد له بالبراهين الساطعة والأدلة الدامغة والحجة العقلية في كون قريش أقدر على إدارة الأمور في دولة الإسلام من غيرها، وإن العرب سيكونون أكثر طوعاً لقريش\nكان ممكن ساعتها الأنصار يرفضوا الامتثال لكلام أبي بكر؛\nلأن الأنصار كانوا مهيئين نفسياً لتولي الحكم،\nوأدلتهم العقلية قوية، وحجتهم المنطقية مقبولة، ويُخشى عليهم ألا ينقادوا بهدوء لأمر الله ولرسوله،\nوكانت هتبقى كارثة فعلا لو رفضوا الانقياد لكلام أبي بكر،\nوحتى لو كانوا وافقوا كان ممكن يوافقوا مكرهين وفي نفوسهم شيء،\nواحنا عايزين:\n\"لَا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا\"\nفمن الحكمة إن الواحد ميطلبش أمر صعب أو عسير من أحد إلا بعد أن تهيئته نفسياً، \nيعني لا تكن عوناً للشيطان على أخيك، واقدر للأمر قدره، وخاطبوا الناس على قدر عقولهم، وراعوا حالتهم النفسية والمزاجية،\nوهو ده إللي عمله أبو بكر رضي الله عنه؛ عالج الأمر بحكمة، وتدرج معاهم في إيصال الحكم، \nولما جاء عرض الحكم عليهم قبلوه بدون أي تردد، واتبعوه دون شك وتقبلوا الأمر ومبقاش في نفوسهم أي حرج وسلموا تسليما كاملا لكلام رسول الله ﷺ \nوعلى فكرة الحديث إللي قاله أبو بكر رضي الله عنه مش هو الحديث الوحيد إللي بيحمل نفس المعنى، \nده في أحاديث تانية كتير غير الحديث ده، لكن الصحابة إللي كانوا سمعوا الأحاديث دي من رسول الله ﷺ وأخبروها للناس بعدين مكنوش حاضرين في السقيفة،\n《وبالمناسبة الأحاديث دي كلها صحيحة\n》\nيعني مثلا حديث في البخاري بيرويه معاوية بن أبي سفيان عن رسول الله ﷺ بيقول:\n\"إنّ هذا الأمرَ في قريش لا يُعاديهم أحد إلا كَبّه الله على وجهه ما أقاموا الدين\"\nلكن معاوية رضي الله عنه مكنش حاضر في السقيفة، وغيره من الصحابة يروي أحاديث بنفس المعنى ولم يكونوا حاضرين،\nلكن مع ذلك لما أبو بكر رضي الله عنه قال الحديث محدش اعترض ولا ردّ الحديث وقال إن الكلام ده غير صحيح أو واحد قام وقعد يفسّره بمعنى تاني خالص غير المعنى الظاهر\n  \nكلام رسول الله ﷺ في الأحاديث المختلفة واضح إن الخليفة من قريش\nو هذا الشرط هو ما عليه جماهير علماء المسلمين، \nومُجمَع عليه من الصحابة والتابعين والأئمة الأربعة.\nأنا بقولكم الكلام ده لأن في ناس بتكذّب الأحاديث دي وبيقولوا إنها بتدعو للتعصب القبلي وإن الإسلام أصلا جاء لإلغاء التعصب وكلام كتير كده الغرض منه الطعن في السُّنة وفي أحاديث رسول الله ﷺ\nفخليكم عارفين إن شرط الأئمة من قريش ده حديث رسول الله ﷺ وعليه إجماع من عهد الصحابة وكل المسلمين ولم يخالفهم إلا أهل البدع زي الخوارج وبعض المعتزلة وغيرهم\n☆ وطبعا هيطلع لنا سؤالين مهمين محتاجين الإجابة عليهم:\n◇السؤال الأول:\nموضوع إن الخلافة تكون في قريش فقط ده، هو فعلا مش كده هيبقى تعصب لقبيلة بعينها\nيعني هل الإسلام دين عنصري جاء لنشر سيادة قريش وانتقاص حق بقية المسلمين في المساواة معهم وحقهم في تولي الخلافة\nثم فين حديث رسول الله ﷺ:\n\"اسمعوا وأطيعوا، وإنْ وَلِيَ عليكم عبدٌ حبشِي كأن رأسه زبيبة\"\nوفين:\n\" أَلَا لَا فَضْلَ لِعَرَبِيٍّ عَلَى أَعْجَمِيٍّ وَلَا لِعَجَمِيٍّ عَلَى عَرَبِيٍّ وَلَا لِأَحْمَرَ عَلَى أَسْوَدَ وَلَا أَسْوَدَ عَلَى أَحْمَرَ إِلَّا بِالتَّقْوَى\"\nبراحة كده وواحدة واحدة،\nبداية كده اختصاص قريش بالخلافة هو تشريع من رب العالمين، \nيعني لا هو اجتهاد من رسول الله ﷺ ولا اجتهاد من الصحابة، ولا قبيلة قريش هي إللي فرضت نفسها\nفلما يأتي التشريع من الله فيجب على الجميع أن يسمع ويطيع ويرضى بدون أي نقاش\nواحنا عارفين إن ربنا عز وجل ولا يفعل شيء إلا لحكمة،\nفاحنا بنعرف وبنسأل عن الحكمة من باب زيادة الإيمان واطمئنان القلب مش من باب الاعتراض على أمر الله،\nتمام كده\nنيجي بقى للتفصيل،\nقريش هي أفضل قبائل العرب بنص الحديث عن رسول الله ﷺ:\n\"إن الله اصطفى قريشاً من كنانة، واصطفى من قريش بني هاشم، واصطفاني من بني هاشم\"\nفالظن أن يكون الخير في العرب أعظم منه في الأجناس الأخرى،\nواحنا اتكلمنا في بداية السيرة خااالص عن أسباب اختصاص العرب أصلا بحمل رسالة الإسلام، وقلنا إن فيهم صفات مش موجودة في حد غيرهم،\nوالظن أن يكون الخير في قريش أعظم منها في قبائل العرب الأخرى،\nعشان كده كان منهم رسول الله ﷺ أشرف خلق الله تعالى الذي لا يُماثله أحد في قريش، فضلاً عن وجوده في سائر العرب وغير العرب\nفالحكمة بقى إن ربنا جعل الخلافة في قريش هي زي ما قال أبو بكر رضي الله عنه للأنصار:\n\"ولن تعرِفَ العربُ هذا الأمرَ إلَّا لهذا الحيِّ مِن قريشٍ هم أوسطُ العربِ نسبًا ودارًا\"\nيعني محدش هيرضى إنه يخضع لقبيلة إلا لقريش، والهدف أصلا توحيد كلمة المسلمين\nوطبعا الموضوع مفهوش أي تعصب خالص؛ لأن اشتراط الخلافة في قريش ليست على الإطلاق ولكن مشروطة بإقامتهم للدين زي ما رسول الله ﷺ قال في حديث معاوية إللي قلناه من شوية:\n《 ما أقاموا الدين》، وإلا فإن صاحب الدين يُقدم حتى لو لم يكن من قريش\nوالكلام كله لا يتعارض إطلاقا مع حديث العبد الحبشي إللي قلناه من شوية؛ لأن المقصود من الحديث هو طاعة من ولّاهُ الإمام، وإن كان حبشيًا، \nيعني إللي الخليفة يعيّنه؛ المطلوب من الناس إنهم يطيعوه أيا كان هو مين أو جنسه إيه مادام لا يأمر بمعصية الله،\nلكن مش إن الخليفة يكون الخليفة من الحبشة؛ لأ، لأن الخليفة العام للمسلمين زي ما قلنا يكون من قريش، أما أمراء المسلمين الذين ينُوبون عن الخليفة فلا يُشترط فيهم أن يكونوا من قريش.\n《في معنى تاني في موضوع تولي العبد الحبشي وهو أن يكون إمام مُتغلّب، وده موضوع تاني خالص مش موضوعنا هنا دلوقتي》\n¤المهم،\nفي هنا ملحوظة في الحديث بالنسبة لنقطة عبد حبشي،\nالحديث من باب ضرب المثل،\nلأن العبد لا يكون خليفة؛ لأن من شروط الخليفة إنه يكون حر وليس عبد،\nزي كده لما رسول الله ﷺ بيقول:\n\"مَنْ بَنَى مَسْجِدًا لِلَّهِ كَمَفْحَصِ قَطَاةٍ ، أوْ أَصْغَرَ ، بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ\"\nيعني إللي يبني مسجد لله بحجم مَفْحَصِ قَطَاةٍ أو أصغر، الله يبني له بيت في الجنة، \nومَفْحَصِ قَطَاة معناه المكان إللي يبيض فيه طائر القَطَا داخل العش بتاعه، وانتم عارفين عش الطائر صغير أد إيه، \nوالهدف من بناء المسجد هو إقامة الصلوات فيه،\nفإزاي الواحد هيصلي في مكان صغير جدا بالحجم ده؟\nفالمقصود من الحديث ضرب المثل،\nيعني مهما كان حجم المسجد إللي هتبنيه لله؛ ربنا هيجازيك ويبني لك بيه بيت في الجنة،\nفحديث العبد الحبشي نفس المعنى، \nمهما كان الشخص إللي الإمام هيولّيه عليكم = أو هو نفسه يتولى عليكم كحاكم مُتغلب ومش من قريش= مش عاجبكم أو انتم مستقذرينه فانتم يجب عليكم طاعته ما دام يُقيم فيكم كتاب الله ولم يأمركم بمعصية \n◇السؤال الثاني:\nطيب قريش كانت معروفة في بداية الإسلام وفضلوا معروفين فترة بعد كده،\nلكن بعد الفتوحات الإسلامية وخروج القُرشيين وبقية العرب من الجزيرة وانتشارهم في كل مكان على مدار السنين، احنا بقى هنعرفهم إزاي عشان نجعل فيهم الخلافة والموضوع بقى معقد\nبكل بساطة، أي حد يتوافر فيه شرط إقامة الدين في المسلمين يكون هو الخليفة\nوهو ده إللي استند عليه العثمانيون في خلافتهم للمسلمين\nانتم عارفين إن العثمانيين مكنوش من قريش ومع ذلك كانت لهم القوة، وكانت لهم الغَلَبة، وكان لهم السمع والطاعة، وهو ده المقصود من الخلافة،\nيعني ما داموا بيحكموا بكتاب الله عز وجل وجمعوا الأمة على ذلك فلماذا لا يكونون هم الخلفاء؟ \nوبالذات إن في زمن العثمانيين لم يكن لقريش شَوْكة ولا قوة، فجمع العثمانيون الأمة تحت راية كتاب الله وسنة رسوله ﷺ\n☆طبعا يا جماعة موضوع الخلافة والإمامة ده موضوع فقهي طوييييل \nأنا قلت لكم فيه الخطوط العريضة إللي تهمنا واحنا بنتكلم عشان نعرف بس الأمور كانت ماشية إزاي مع الصحابة،\nوهتلاقوا في التعليقات مواقع فيها الموضوع بالتفصيل الممل\nيبقى خلاصة الموضوع دلوقتي إن الصحابة جميعاً انقادوا وسلّموا تماماً لحديث أبي بكر الصديق رضي الله عنه ؛ لأنه تشريع، وسكنت السقيفة، وذهب الخلاف، واستقر الناس على قريش\nمين بقى إللي يختاروه من قريش\nده إللي هنعرفه الجزء الجاي إن شاء الله \nمصادر جزء النهاردة في التعليقات"}, {"n": 266, "l": "الجزء 240 والاخير | احداث السنه الحادية عشرة من الهجرة | دفن رسول الله", "u": "", "t": "دفنو رسول الله \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_أربعون_والأخيرة\n#أحداث_السنة_الحادية_عشرة_من_الهجرة\n#دَفْن_رسول_الله\nوقفنا المرة إللي فاتت عند استقرار الأمور في السقيفة واتفاق الجميع على إن الخليفة يكون من قريش،\nلكن السؤال المهم بقى: يا ترى يختاروا مين يكون هو الخليفة\nفي البداية كان أبو بكر رضي الله عنه رشح للخلافة عمر وأبا عبيدة،\nفدلوقتي الترشيح ما زال قائم، لكن عمر وأبو عبيدة كان لهم رأي تاني،\nأبو عبيدة رضي الله عنه قال لأبي بكر:\nلا ينبغي لأحد بعد رسول الله ﷺ أن يكون فوقك يا أبا بكر ! أنت صاحب الغار مع رسول الله ﷺ، وثاني اثنين، \nوأمّرك رسول الله ﷺ حين اشتكى، وصليت بالناس، فأنت أحق الناس بهذا الأمر\nيعني مينفعش حد يكون أمير عليك، انت إللي كنت مع رسول الله ﷺ في الهجرة وفي الغار زي ما ربنا ذكرك في القرآن، ولما رسول الله ﷺ كان مريض خلاك انت مكانه تصلي بالناس وترعى شؤونهم؛\nفأنت احق بالخلافة من أي أحد، فهنا عمر رضي الله عنه قال للأنصار:\n\" يا معشر الأنصار، ألستُم تعلمون أن رسول الله ﷺ قد أمَر أبا بكر يَؤُم الناس؟!\nفأيُّكم تطيبُ نفسه أن يتقدم أبا بكر رضي الله عنه؟\nيعني مين إللي نفسه تكون راضية إنه يكون إمام لأبي بكر ورسول الله ﷺ نفسه هو إللي خلاه إمام للناس؟\n فقال الأنصار: نعوذ بالله أن نتقدم أبا بكر\nفهنا عمر رضي الله عنه قال لأبي بكر:\nابسُطْ يدَك يا أبا بكرٍ.\nفبسَطها، فبايَعه عمر، وقام أُسيد بن حضير زعيم الأوس، وقام بشير بن سعد رضي الله عنه يستبقان للبيعة، \nيعني كانوا بيسابقوا بعض لمبياعة أبو بكر بالخلافة، فهنا وَثَب أهل السقيفة يَبْتَدِرُون البيعة، \nيعني قفزوا من أماكنهم ناحية أبي بكر بيسابقوا بعض، كل واحد عايز يبايع هو الأول\nفبايع الحُباب بن المنذر وبايع ثابت بن قيس، وبايع زيد بن ثابت رضي الله عنهم أجمعين، \nوبايع كل الأنصار في السقيفة ما عدا سعد بن عبادة رضي الله عنه، بايع بعد كم يوم كده،\nوهو معذور لأنه ساعته كان مريض والدنيا كانت زحمة وحصلت أحداث كتير،\nفلما الأمور هدأت وخف مرضه بايع رضي الله عنه\nدي كده كانت البيعة الأولى وحصلت بيعة تانية في المسجد لأبي بكر رضي الله عنه وفي تفاصيل كتير حصلت بس ده مش موضوعنا دلوقتي،\nواحنا بنتكلم عن الخلفاء هنتكلم عن الأحداث دي بالتفصيل إن شاء الله، وهنتكلم عن الأحاديث إللي كان فيها إشارة لاستخلاف أبي بكر رضي الله عنه\nاحنا بقى هنسيب كل الأحداث دي ونرجع لحُجرة السيدة عائشة إللي كان فيها رسول الله ﷺ ونشوف حصل إيه، فهو ﷺ لم يُدفن حتى الآن\nلما بيموت أي مسلم المفروض إنه بيتغسّل وبيتكفن ومعروف بيتعمل معاه إيه، \nلكن موضوع تغسيل وتكفين ودفن رسول الله ﷺ يُعتبر قضية حساسة جداً ومُحيرة، \nوهي من القضايا الأُولى إللي مطلوب من الصحابة إنهم يأخذوا فيها قرار بدون ما يكون رسول الله ﷺ موجود معاهم،\nكان في حجرة رسول الله ﷺ مجموعة من الصحابة هم إللي هيقوموا بتغسيله هم:\n◇علي بن أبي طالب رضي الله عنه، وكان هو إللي يغسله ﷺ.\n◇أسامة بن زيد ومولى رسول الله ﷺ، وكانا يصبان الماء.\n◇ العباس بن عبد المطلب عم النبي ﷺ واثنين من أبناء العباس هما قَثَم والفَضل، وكانوا يقلّبونه ﷺ.\n◇أوْسُ بن خَوْلِيّ الأنصاري رضي الله عنه، وكان يسند رسول الله ﷺ على صدره.\nاحتار الصحابة في تغسيل رسول الله ﷺ، هل ينزعون ملابسه كما ينزعزن ملابس باقي الموتي عند الغسل إلا ما يستر العورة؛ ولّا يغسلونه وهو عليه ثيابه؟\nلأن هناك من الأحكام الفقهية ما قد يكون خاص به ﷺ وهناك ما قد يكون عامًّا على عموم المسلمين\nفلما اختلفوا ألقى اللهُ عليهم النومَ ثم كَلّمَهم مُكلّمٌ من ناحيةِ البيتِ لا يدرون مَن هو أنِ اغسلوا النبيَّ ﷺ وعليه ثيابُه،\nيعني اختلفوا في الرأي، مجموعة قالت ننزع ملابسه ومجموعة قالت لأ نغسله وعليه ملابسه،\n فهنا ربنا خلاهم كلهم يناموا، وبعدين سمعوا حد بيكلمهم من جانب البيت ميعرفوش هو مين وبيقول لهم إنهم يغسلوا رسول الله ﷺ وعليه ثيابه،\nممكن يكون إللي كلمهم ده مَلك والله أعلم\nفقاموا إلى النبيِّ ﷺ فغسلوه وعليه قميص، يعني كانوا يصبوا الماء على الملابس إللي كان رسول الله ﷺ لابسها\nويُدَلِّكونَه بالقميصِ دونَ أيديهم\"\nيعني كانوا بيغسلون جسمه من فوق الثياب ولا يَمَسُّونَ بَشَرَتَه ﷺ بأيديهم\n☆السيدة عائشة كانت تقول:\n\"لو استَقبلتُ من أمري ما استدبرتُ ، ما غسَلَهُ إلَّا نساؤُهُ\"\nيعني السيدة عائشة بتقول لو كانت عَلِمت وظَهَر لها ما كان مِن تغسيلِ رسولِ اللهِ ﷺ لكانت زوجات رسول الله ﷺ \n هنَّ اللَّاتي غَسَّلوا النَّبيَّ ﷺ،\nلكن لأن السيدة عائشة كانت حزينة جدا لموت رسول الله ﷺ فالفكرة دي لم تأتِ في بالها،\nوهنا دليل على أن المرأة يجوز أن تغسل زوجها والعكس،\nيعني الرجل يجوز إنه يغسّل زوجته،\nوطبعا الكلام إللي بيقول إن المرأة إذا ماتت أصبحت أجنبية عن الزوج ومينفعش يشوفها ولا يدخل عليها والكلام ده، كل ده غير صحيح\nبعد ما غسلوا رسول الله ﷺ؛ كفّنوه في ثلاثة أثواب بيض يمانية من القطن ليس فيها قميص ولا عِمَامة،\nوكان تغسيل رسول الله ﷺ في صباح يوم الثلاثاء، يعني هو مات يوم الإثنين والصحابة غسلوه يوم الثلاثاء وتم دفنه في ليلة الأربعاء على الصحيح من أقوال أهل العلم؛\nلأن في قول تاني بيقول إنه دُفن في آخر ليلة الثلاثاء قُرب الصبح، لكن القول الأول هو الأصح.\n☆ثواني كده\nيعني الصحابة تركوا رسول الله ﷺ أكثر من يوم كامل من غير ما يغسّلوه ولا يدفنوه\nطب إزاي ورسول الله ﷺ كان قالهم:\n\" أَسْرِعُوا بِالْجَنَازَةِ ، فَإِنْ تَكُ صَالِحَةً فَخَيْرٌ تُقَدِّمُونَهَا إِلَيْهِ ، وَإِنْ تَكُ غَيْرَ ذَلِكَ فَشَرٌّ تَضَعُونَهُ عَنْ رِقَابِكُمْ\"\nوقال:\n\"إِذَا مَاتَ أَحَدكُمْ فَلَا تَحْبِسُوهُ وَأَسْرِعُوا بِهِ إِلَى قَبْره\"\nفإزاي بعد ده كله الصحابة يسيبوا رسول الله ﷺ الفترة دي كلها من غير غسل ولا دفن\nمبدإيا كده عشان نبقى عارفين،\nأجساد الأنبياء لا تتغير بعد الموت زي باقي أجساد البشر والأرض لا تأكل أجساد الأنبياء،\nيعني حتى هذه اللحظة جسد رسول الله ﷺ كان زي ماهو لم يتغير،\nوالدليل على كده قول رسول الله ﷺ:\n\"إن الله عز وجل قد حرّم على الأرض أن تأكل أجسادَ الأنبياء عليهم السلام\"\nممكن بعض الناس الصالحين والشهداء أجسادهم تفضل زي ما هي لا تتغير ولا تتحلل بعد الموت وده بيكون كرامة من الله لهم، زي كده شهداء أحد.\nنيجي بقى لأسباب تأخير دفن رسول الله ﷺ:\n◇أولا:\nموت رسول الله ﷺ كان أمراً عظيماً، ودُهش له الناس، وطاشت قلوبهم، \nواحنا شوفنا عمر القوي كان رد فعله عامل إزاي، فهم لو بإيدهم مش هيدفنوه أصلا،\nيعني احنا لنا بيموت لنا حد عزيز بنبقى مش عايزين نفارقه أصلا وبنبقى مش مستوعبين إزاي هندفنه في التراب ونرجع من غيره،\nفما بالكم إن إللي بنتكلم عنه ده مش أي عزيز، ده رسول الله ﷺ إللي كان أحب للصحابة من أنفسهم ومن آبائهم وأبنائهم وكل شيء في حياتهم،\nفهل من الممكن إن الصحابة يدفنوا رسول الله ﷺ بعد وفاته مباشرة كده؟!\nأكيد لأ طبعا\nده حتى السيدة فاطمة هتقول لأنس بعد ما هيدفنوا رسول الله ﷺ:\nأطابَت أنفسكم أن تَحثُوا على رسول الله ﷺ التراب؟!\nيعني انتم رضيتم إنكم تضعوا التراب على رسول الله ﷺ وتغطوه بيه وتسيبوه وتمشوا؟!\nفالأمر كان أشد عليهم مما نتخيل والله\nفإزاي بقى نقول إن الصحابة تأخروا في دفن رسول الله ﷺ \n◇ثانيا:\nإختلافهم في طريقة تغسيله زي ما قلنا، وكمان اختلافهم في المكان إللي هيدفن فيه.\n◇ثالثا:\nاهتمام الصحابة بجمع شمل الأمة وحمايتها من التفرّق إللي  يعتبر سبب رئيسي في زوالها، \nففي يوم الإثنين إللي مات فيه رسول الله ﷺ تم اختيار أبا بكر للخلافة وتمت له البيعة وأصبح هو خليفة المسلمين واستقرت الأوضاع في المدينة،\nوبكده تمت حماية المدينة من فتنة شديدة كانت ممكن تحصل ويضيع كل تعب رسول الله ﷺ في السنين إللي فاتت دي كلها\n◇رابعا:\nصلاة الصحابة على رسول الله ﷺ رجالاً ونساء وصبياناً منفردين بدون إمام يؤمهم، \nفبعد ما انتهى الصحابة من تغسيل وتكفين رسول الله ﷺ وضعوه على فراشه في حجرته، وبدأ الناس يدخلون على رسول الله ﷺ للصلاة عليه في مجموعات،\nيعني كان بيدخل مجموعة يصلوا عليه صلاة الجنازة ويخرجوا،\nثم يدخل مجموعة أخرى يصلوا عليه ويخرجوا وهكذا، وكانوا يصلون مُنفردين، كل واحد لوحده بدون إمام،\nفصلى عليه أولاً أهل بيته ﷺ وعشيرته، \nثم المهاجرون، ثم الأنصار، ثم بقية الرجال في المدينة، ثم دخلت النساء فصلت عليه، ثم بعد ذلك الصبيان، حتى صلى عليه كل المؤمنين إللي كانوا في المدينة.\nفكل الأسباب دي مجتمعة كانت  سبب في تأخر دفن رسول الله ﷺ.\n☆طب سؤال،\nليه الصحابة مصلوش صلاة الجنازة جماعة، وكل واحد صلى لوحده ومكنش في إمام لصلاة الجنازة على رسول الله ﷺ \nهو الموضوع على خلاف بين العلماء، وذكروا أسباب منها\n◇أولا:\nتنافُس الصحابة في تحصيل البركة من الصلاة عليه على وجه الانفراد والخصوصية من غير ما يكون حد فيهم تابع لإمام، يعني محدش فيهم كان يَقبل أن يتوسط بينه وبين رسول الله ﷺ أحد في الصلاة؛ عشان ينال الأجر والبركة.\n◇ثانيا:\nتعظيم النبي ﷺ في نفوسهم واحترامه، فكانوا يهابوا أن يتقدم أحد بين يديه يؤم الناس في الصلاة عليه، \nفقد كان عليه الصلاة والسلام إمام الناس وقائدهم وهاديهم، \nفلم يجرؤ أحد أن يَقف موقفه وأن يُنصّب نفسه مكانه بعد وفاته وبغير إذنه ﷺ،\nيعني هم كرهوا أن يتخذوا إماماً بين يدي رسول الله ﷺ.\n☆وهنا عايزين نوضح حاجتين:\n¤أولا:\nالحديث إللي رسول الله ﷺ وصّى فيه الناس إنهم يصلوا عليه فُرادى بدون إمام لما يموت؛ حديث باطل غير صحيح\n¤ثانيا:\nالحديث إللي بيقول إن رسول الله ﷺ طلب من الصحابة إنهم ينتظروا بعد تجهيزه ساعة محدش يدخل عليه حتى يصلي عليه ربه عز وجل ويصلي عليه الملائكة؛\nحديث غير صحيح\nوبالعقل حتى، لا يمكن أن يكون صحيحا، فصلاة الله على رسوله ﷺ هي ثناؤه عليه في الملأ الأعلى، وقد أثنى الله عليه في حياته ﷺ\n◇أنا نبهت على النقطتين دول بالذات؛ لأن في خطباء بيقولوهم، وأنا سمعت الكلام ده بنفسي، ولما بحثت لقيت إن الكلام ده غير صحيح، والمصادر هتلاقوها في التعليقات\nطبعا بسبب إن أهل المدينة كلهم صلوا على رسول الله ﷺ فالموضوع أخد وقت،\nوبقينا في ليلة الأربعاء الرابع عشر من شهر ربيع الأول للسنة الحادية عشرة للهجرة،\nدلوقتي جاء وقت دفن رسول الله ﷺ،\nاختلف الصحابة في مكان دفن رسول الله ﷺ، هل يدفنوه في البقيع مع باقي المسلمين، أم يدفنوه في المسجد؟\nفأخبرهم أبو بكر رضي الله عنه أن رسول الله ﷺ قال:\n\"ما قبَضَ اللهُ نَبيًّا إلَّا في المَوضِعِ الذي يُحِبُّ أنْ يُدفَنَ فيه. ادفِنوه في مَوضِعِ فِراشِه\"\nيعني من خصائص الأنبياء إن المكان إللي بيموتوا فيه هو ده مكان دفنهم،\nورسول الله ﷺ كان مات على فراشه، فرفع الصحابة الفراش وبدأوا يحفروا لقبر رسول الله ﷺ.\nلكن اختلفوا هل يُشَق لرسول الله ﷺ في قبره أم يُلَحّد؟\nفقد كان رجلان في المدينة واحد منهم  يَلحَدُ والثاني يَشُقُّ،\nفقالوا:\nنستخيرُ ربَّنا، ونبعثُ إليْهما، فأيُّهما سبقَ ترَكناه، فأُرسلَ إليْهما، فسبقَ صاحبُ اللَّحدِ فلحدوا للنَّبيِّ ﷺ.\nيعني هم استخاروا في الشق أو اللحد، فقالوا احنا نبعت لهم وإللي ييجي الأول هو إللي هنستعمل طريقته، فجاء الرجل إللي بيَلحَد، فلحَد لرسول الله ﷺ.\n☆إيه موضوع اللحد والشق ده\n◇صفة الشَّق:\nهو أن يُحفَر في وسَط القبر حفرة على قَدْر الميت، ويُبنى جانباها بالطوب اللَّبِن حتى لا تنضم على الميت، \nويُوضع فيها الميت على جنبه الأيمن مُستقبلاً القبلة، \nيعني يا جماعة بيتحفر حفرة كبيرة عادي، وفي نص الحفرة تحت بيتحفر حفرة تانية على أد الميت،\nوبعدين يتبنى بالطوب على الجانبين،\nفكده الجانبين هيكونوا مرفوعين والميت في النص، وبعد كده يتعمل زي سقف للحفرة دي بأحجار أو غيرها، بحيث إنها تبقى مرفوعة عن الميت ولا تمسه،\nوبعدين يوضع التراب فوقها.\n◇صفة اللَّحْد: \nبيتحفر برده حفرة كبيرة، وفي جدار الحفرة الأقرب إلى القبلة بيتم حفر فيه مكان على أد الميت، ويُوضع فيه الميت على جنبه الأيمن مستقبل القبلة،\nيعني وجهه يكون للداخل، ثم تُسد هذه الحفرة بالطوب اللِّبن خلف ظهر الميت، ثم يوضع عليه التراب ويتم ردم القبر.\nهتلاقوا صورتين في التعليقات بتوضح الفرق بين اللحد والشق\n أو ممكن تبحثوا عنها على النت وهتعرفوا الفرق.\nواللحد والشق جائزان بإجماع العلماء، لكن اللحد أفضل؛ لأنه هو الذي فُعل بقبر رسول الله ﷺ.\nبعد ما حفروا القبر على هيئة اللحد وضعوا فيه رسول الله ﷺ وأهالوا عليه التراب\nوبكده تم غلق أهم صفحة من صفحات تاريخ البشرية\nيقول أنس بن مالك رضي الله عنه:\n\"وما نفَضنا عنِ النَّبيِّ ﷺ الأيديَ حتَّى أنْكَرْنا قلوبَنا\"\nيعني إزاي هيقدروا يعيشوا في الحياة بدون رسول الله ﷺ،\nوإزاي هم هيمشوا على الأرض ورسول الله ﷺ يرقد تحت الأرض،\nمش لاقيين الصَّفاءِ والرِّقَّةِ والأُلفَةِ إللي كانت في قلوبهم لما كان رسول الله ﷺ بينهم،\nالقلوب وكأنها ليست القلوب، كان رسول الله ﷺ يمدها بنور وهدى وأمان وراحة واطمئنان،\nأما الآن فقلوبنا ليست هي القلوب التي كانت يوم كان رسول الله ﷺ حياً بين أَظُهرِنا،\nالسيدة فاطمة بعد دفن رسول الله ﷺ قالت لأنس:\n\"أطابت أنفسكم أن تحثوا على رسول الله ﷺ التراب؟!\"\nهان عليكم تحطوا تراب على رسول الله ﷺ!!\nأكيد لأ طبعا، لكن هيعملوا إيه\nده قدر كتبه الله عز وجل على كل عباده، ولا راد لقضائه، \nولعل الشيء الوحيد إللي كان بيصبّر الصحابة على فراق رسول الله ﷺ ويصبرنا احنا كمان إنهم على موعد معه يوم القيامة عند الحوض،\nفقد كان رسول الله ﷺ يقول لهم:\n\"موعدَكم الحوضُ\"\nوهو موعدنا مع رسول الله ﷺ يوم القيامة، ولعل الله أن يجمعنا به في الجنة مع صحابته الكرام رضي الله عنهم أجمعين بحبنا لهم؛\nفقد قال رسول الله ﷺ لرجل سأله عن الساعة:\nوماذا أعددت لها؟\nفقال الرجل لرسول الله ﷺ:\n لا شيء إلا أني أحب الله ورسوله، فقال ﷺ:\n 《أنت مع من أحببت》\nفنحن نحب رسول الله ﷺ ونحب أبا بكر وعمر وعثمان وعلي وحمزة ومصعب وياسر وعمار وسمية وأنس بن النضر وسعد بن معاذ،\n وسلمة بن الأكوع ومحمد بن مسلمة وعبد الله بن أُنيس وأسيد بن حضير وسعد بن عبادة وأبو هريرة و......\nنحن نحب المهاجرين والأنصار ونحب كل الصحابة ونرجوا أن نكون معهم بحبنا لهم وإن لم نعمل بمثل أعمالهم.\nنسأل الله عز وجل كما آمنا برسولنا ﷺ ولم نره أن يحيينا على سنته ويُميتَنا عليها ويحشرنا معه ويجعلنا من رفقائه في الجنة"}, {"n": 267, "l": "الخاتمة", "u": "", "t": "《خاتمة السيرة النبوية 》\n♡كده يا جماعة احنا خلصنا قصص الأنبياء من أول خلق آدم عليه السلام وحتى خير الخلق محمد ﷺ، \nفالحمد والفضل والمِنّة لله وحده\nوبكده نكون خلصنا الكلام بالتفصيل عن رُكنين من أركان الإيمان وهما:\nالإيمان برُسل الله وبالكتب التي أنزلها الله على رسله، \nفجزاكم الله خيرا على صبركم معي \nوجزاكم الله خيرا على دعمكم وتشجيعكم وإعطائي الفرصة إني أتكلم عن رسول الله ﷺ والصحابة\nو السبب إللي خلاني أكتب عن رسول الله ﷺ وأحاول أوصل حياته للناس\n مكنتش بحب القرائه خالص بس سمعت وقرأت قصه من قصص الأنبياء وعجبتني جدا وكنت ديما اتخيل ايام الرسول كانو عايشين ازاي ف حبيت اقرأ وادور وابحث ع القصص ومن هنا بدأت اقرأ \nواستمر الحال لحد ما سمعت مجموعة أحاديث متتالية:\nقَالَ عمر لرسول الله ﷺ: \nوَاللَّهِ يَا رَسُولَ اللَّهِ لأَنْتَ أَحَبُّ إِلَيَّ مِنْ كُلِّ شَيْءٍ إِلا نَفْسِي، فَقَالَ رَسُولُ اللَّهِ ﷺ:\n لا، وَالَّذِي نَفْسِي بِيَدِهِ، حَتَّى أَكُونَ أَحَبَّ إِلَيْكَ مِنْ نَفْسِكِ، \nقَالَ عُمَرُ:\nفَأَنْتَ الآنَ، وَاللَّهِ، أَحَبُّ إِلَيَّ مِنْ نَفْسِي، فَقَالَ رَسُولُ اللَّهِ ﷺ: الآنَ يَا عُمَرُ\"\nوحديث:\nثلاث من كُن فيه وجد حلاوة الإيمان: \nأن يكون الله ورسوله أحبَّ إليه مما سواهما، وأن يحبَّ المرء لا يحبه إلا لله، وأن يكرهَ أن يعود إلى الكفر كما يكره أن يُقذفَ في النار\"\nوحديث:\n\"لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده والناس أجمعين\"\nده غير محاضرة علموا أولادكم حب الصحابة للشيخ أبو إسحاق الحويني \nفهنا كانت نقطة التحول، أنا لازم أعرف مين هو محمد رسول الله ﷺ ده، ومين هم الصحابة دول، \n 《\nالمهم أنا عَكفْت على محاضرات السيرة لحد ما خلصتهم ، \nوبعدها قلبي تغير تماما من ناحية كل حاجه ف الدنيا وبدأت اعمل زي رسول الله  ﷺ والصحابة وعرفت مين هو رسول الله ﷺ،\nوعرفت الأذى إللي اتعرض له في سبيل تبليغ الدين لنا، \nوعرفت كمية الابتلاءات إللي تعرض لها،\nوعرفت معنى إن أي حد يُصاب بمصيبة فليتذكر مصابه برسول الله ﷺ فالمصيبة فيه هي أعظم المصائب،\nوعرفت ليه لازم نتعلم حب الصحابة ونعرف مكانتهم ومنسمحش أبدا لأي حد إنه يتطاول عليهم، \nوإن الدين بتاعنا ده وصّلوه لنا بالدم في حين إننا مضيعينه ومش متمسكين بيه وهو أول حاجة بنفرط فيها ومش بنبذل أقصى طاقتنا عشان نوصله لكل البشر،\nالسيرة من بعدها  بقت جزء من حياتي، أنا مش فاكر عدد المرات إللي سمعت فيها السيرة،\nكل إللي فاكراه إني كنت عايشة مع رسول الله ﷺ من خلال أحداث السيرة،\nبقيت أدور على أي محاضرات بتتكلم عن رسول الله ﷺ وعن الصحابة، بقوا فعلا كل حياتي، وسبحان مغير القلوب،\nبقى همي إني أوصل للناس وأعرفهم مين هو رسول الله ﷺ ومين هم الصحابة وأحاول إني أزرع حبهم في القلوب من باب إني اعرف الناس مين رسول الله ،\nو في ناس كانت فاهمه رسول الله غلط، واصل لها فكرة غلط أو فكرة سيئة عن رسول الله ﷺ وعن الصحابة،\nفلما يقرأوا السيرة الصحيحة عن رسول الله ﷺ ويعرفوا الرد على الشبهات زي ما شرحت من خلال الحلقات؛\nساعتها هيغيروا وجهة نظرهم ويحبوا رسول الله ﷺ فعلا ليذوقوا طعم الإيمان ولما يقابلوه على الحوض يشربوا من حوضه ولا يُقال لهم:\nسُحقا لمن بدّل بعدي وغيّر\n♡أتمنى إني أكون زرعت ولو بذرة حب بسيطة لرسول الله ﷺ وللصحابة في قلب كل قارئ،\nوإني أكون عرّفتكم ببعض تفاصيل حياته ﷺ، وإلا فالسيرة طويلة ومليانة بالأحداث وعجائبها لا تنتهي،\nوأتمنى طبعا إنكم زي ما عرفتم عن رسول الله ﷺ والصحابة إنكم تعرّفوا غيركم، \nوإنكم تتبعوهم وتدافعوا عنهم ضد الناس إللي بتهاجمهم ومش عارفة قدرهم.\n♡وأخيرا، \nالسيرة مينفعش نقرأها أو نسمعها مرة وخلاص، دي لازم تكون جزء من حياتنا زي الأكل والشرب كده،\nبالطريقة دي هنقدر نحولها لمنهج حياة نعيشه كأننا كنا عايشين مع رسول الله ﷺ والصحابة،\nوهنفهم آيات القرآن وهنعرف من خلالها الفقه والعقيدة  والتربية وكل ده من غير ما نحس، فلو اتقنّا السيرة؛ اتقنا كل العلوم الشرعية تقريبا في إيدنا\nيعلم الله إني كنت حريص جدا إني أوصلكم المعلومة الصحيحة فقط عن رسول الله ﷺ وإني كنت ببعد عن كل الأحاديث الضعيفة وبوضحها لكم،\nوحتى لو المعلومة أنا عارفاها كنت ببحث عنها تاني وأكثر من مرة وفي مواقع مختلفة عشان أتأكد من صحتها قبل ما أنقلها،\nلكن انتم عارفين إن احنا بشر، ممكن نقع في خطأ أو سهو أو نسيان، فلو كنت فعلا وقعت في حاجة منها فمني ومن الشيطان والله ورسوله منه بَراء،\nوما كان من خير فمن فضل الله وكرمه،\nوأعوذ أن أذكركم به وأنساه.\n♡أختم بأبيات شعرية بسيطة وسهلة، \nتقدروا تقولوا إنها بتعبر عن حياة كل واحد من الصحابة، وإللي المفروض احنا كمان نكون عليها:\nأنا المسلمُ دستورِي ومِنْهاجِي كتابُ الله\nوقائدُ دَربيَ الهادِي محمدُنَا رسول الله\nودارِي موطنُ الإسلامِ ما دَوَّى نداءُ الله\nوأهلِي أمةُ الإسلامِ همْ حِزْبي وحزبُ الله\nوزَادِي بعدَ توحيدِي ونِعمَ الزَّاد تقوَى الله\nأنا المسلمُ قلبِي خافقٌ دومًا بحبِّ الله\nوأقْوَالِي وأعمَالِي أُعطِّرُها بذِكر الله\nفبسمِ اللهِ أَبْدؤُها وأَختِمُها بحمدِ الله\nوهمِّي في الحياةِ هدايةُ الدنيا لدينِ الله\nفَعَيْشِي إنْ أَعِش لله وموتِي في سبيل الله\nأنا المسلمُ لا أَرجو ولا أَخْشى سِوَى ربِي\nعزيزُ النفس لا أَحْنِي لغير الله من صُلْبِي\nسليمُ القلبِ لا أحملُ للناسِ سِوَى الحُبِّ\nغزيرُ الدّمْعِ في المِحرابِ لَيْثُ الغَابِ في الحَربِ\nأنا درعٌ لأوطاني أنا حامِي حِمَى الشَّعبِ\nأنا بالعدلِ والإحسانِ مأمُورٌ وأَمَّارُ\nُأنا نبعٌ لكلِّ الناسِ بالخيراتِ فَوَّارُ\nرحيمُ القلبِ لكني على الطَّاغِينَ جَبَّارُ\nُأنا كالماءِ رقراقٌ أنا كالسيفِ بَتَّارُ\nأنا نَجمٌ أنا رَجْمٌ أنا نُورٌ أنا نارُ\nأنا المسلمُ دستورِي ومِنْهاجِي كتابُ الله\nوقائدُ دَربيَ الهادِي محمدُنَا رسول الله\nودارِي موطنُ الإسلامِ ما دَوَّى نداءُ الله\nوأهلِي أمةُ الإسلامِ همْ حِزْبي وحزبُ الله\nوزَادِي بعدَ توحيدِي ونِعمَ الزَّاد تقوَى الله\n..............\nبما إن السؤال اتكرر كتير جدا فقلت إني لازم أعمل منشور بالإجابة عشان الناس تطمئن\n◇ما هي مصادري في كتابة قصص الأنبياء والسيرة النبوية وقصص القرآن والقصص في الحديث النبوي، وهل أنا أنقل من كتاب معين أم لا؟\nبسم الله والصلاة والسلام على رسول الله وبعد :\n♡سلسلة قصص الأنبياء كتبتها بأسلوب بسيط جدا وسهل أي حد يفهمه سواء الكبار أوالأطفال،\n من أول قصة آدم عليه السلام وحتى قصة رفع عيسى عليه السلام، وستجدون في قصص الأنبياء بعض لقصص القرآن والحديث النبوي،\nأما قصة محمد ﷺ فهي في سلسلة منفصلة لأنها طويلة وفيها تفصيل كبير، وهي سلسلة السيرة النبوية،\nوستجدون فيها باقي قصص القرآن وباقي قصص الحديث النبوي، وكذلك علامات الساعة الصغرى والكبرى وأحداث بعد الموت وأحداث أخرى.\n♡اخترت اللغة العامية بدل من العربية الفصحى لأن الناس للأسف في واقعنا الآن لا يفهمون الفصحى،\nأنا شخصيا بفضل اللغة العربية الفصحى وخصوصا إنها تخصصي في الكلية،\nلكن الغاية عندي والأهم أن الناس يتعرفوا على الدين الصحيح بغض النظر عن اللهجة سواء كانت فصحى أو عامية،\nوربنا قال :\n\"وَمَا أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِ لِيُبَيِّنَ لَهُمْ\"\nففي بعض الأحيان تكون العامية أبلغ في توصيل المعنى للناس إللي مدرستش اللغة العربية الفصحى.\nوربنا ييسر لنا إننا نعمل سلسلة بنفس الأسلوب والبساطة لكن باللغة العربية الفصحى.\n♡الهدف من سلسلة القصص دي هو :\n◇تعريف المسلمين بقصص الأنبياء عشان نقدر نحقق أركان الإيمان الستة،\nوهي: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره.\n◇ربط القصص بالواقع بتاعنا واستخلاص الفوائد والعِبر التي تفيدنا في حياتنا ونقدر نطبقها بسهولة.\n◇نتعلم أساسيات الدين الإسلامي من خلال القصص والرد على بعض الشُّبهات.\n◇نتعلم حب رسول الله ﷺ الحب الحقيقي الذي لا يكتمل الإيمان إلا بحبه ويكون أمامنا القدوة الحسنة إللي نقدر نتبعها بكل اطمئنان.\n◇نعرف مين هم الصحابة، وكانت حياتهم وطاعتهم لرسول الله ﷺ عاملة إزاي عشان نعرف نقلدهم.\n◇نفهم القرآن الكريم لأن ثلث القرآن قصص، وكمان نعرف أسباب نزول الآيات.\n♡بالنسبة للمصادر التي اعتمدتُ عليها في كتابة القصص هي :\nآيات القرآن والأحاديث النبوية الصحيحة والقول الراجح من أقوال المفسرين :\n☆كنت بسمع القصة الواحدة لأكثر من شيخ،\nمثل الشيخ نبيل العوضي وعثمان الخميس وطارق السويدان ومصطفى العدوي ومسعد أنور،\n ومحمد صالح المنجد والشيخ أبو اسحاق الحويني،\n ودكتور راغب السرجاني والشيخ حازم صلاح أبو اسماعيل وغيرهم من المشايخ والعلماء الموثوق في علمهم،\nوبقرأ القصة من كتاب البداية والنهاية لابن كثير، \nوبتأكد من الحديث هل هو صحيح أو ضعيف أم في إختلاف في صحته.\n☆ولو القصة عليها شُبهة بشوف الشّبهة والرد عليها بأقوال العلماء من موقع الإسلام سؤال وجواب وإسلام ويب،\nوطبعا لو أتى في بالي سؤال ممكن حد فيكم يسأله بعمل عليه بحث وبشوف إجابته إيه بالدليل ولو في مثلا سؤال يترتب عليه بروح أشوفه وأنقله لكم.\n☆وبعد كل ده ببدأ كتابة القصة بأسلوبي وبحط الأيات إللي بتدل على الكلام إللي قلته،\nولو في معلومة خطأ منتشرة بين الناس بوضحها وأقول الصحيح منها.\nولو في معلومة من الإسرائيليات التي يجوز نقلها كما قال رسول الله ﷺ:\n \"حدثوا عن بني إسرائيل ولا حرج\" بقول إن القصة دي من الإسرائيليات، \nوهتلاقوا في الجزء الخامس من قصص الأنبياء معنى كلمة إسرائيليات وحكمها وأنواعها.\n ☆التفسير كنت برجع لتفسير ابن الكثير والطبري والبغوي والسعدي والقرطبي.\nحاولت بقدر الإمكان إني أجيب الخُلاصة عشان المعلومة تكون سهلة من غير الدخول في أقوال العلماء إللي تلخبط،\nفالغاية هي تبسيط الدين للناس وإعطاءهم معلومة صحيحة يطبقوها في حياتهم.\n♡كنت حريص جدا إني أنقل المعلومة الصحيحة،\nفكل الكلام إللي قلته في قصص الأنبياء أو السيرة عليه دليل من القرآن أو السنة أو الراجح من جمهور العلماء والمفسرين\n◇ملحوظة هامة:\n♡تمت مراجعة قصص الأنبياء فقط دون السيرة بواسطة الأخت: \n《أسماء محمد لبيب》 جزاها الله عني خيرا وأضافت للقصص نقاط مهمة لتوضيح المعنى،\nفأصبحت قصص الأنبياء عمل مشترك بيني وبينها، فوجب عليّ التنبيه لذلك.\n♡النقطة الأخيرة: \n قال رسول الله ﷺ:\n\"إذا مات ابن آدم انقطع عمله إلا من ثلاث ومنها علم يُنتفع به\"\nأتمنى من إللي يقرأ كلامي أنه ينشر قصص الأنبياء والسيرة بين الناس،\nأولا: لتكون صدقة جارية لنا إذا متنا.\nثانيا: صدقة جارية لمن ينشر العلم النافع لأن الدال على الخير كفاعله،\nوأفضل الصدقة كما قال رسول الله ﷺ :\n\"أفضل الصدقة أن يتعلم المرء المسلم علما ثم يعلمه أخاه المسلم\"\nفنسأل الله البركة والقبول، ولا تنسونا من صالح دعائكم."}]);
